const EXAM_SETS = [{"id":"exam-soc-01","name":"สังคม ม.2 · เรื่องที่ 1 พลเมืองดีวิถีประชาธิปไตย","subject":"สังคมศึกษา","unit":"หน่วยที่ 4 พลเมืองดี · แผนที่ 1","questions":[{"text":"ตำแหน่งของบุคคลในสังคม เรียกว่าอะไร","a":"บทบาท","b":"สถานภาพ","c":"สิทธิ","d":"หน้าที่","correct":1,"explain":"สถานภาพ คือ ตำแหน่งของบุคคลในสังคม ส่วนบทบาทคือการปฏิบัติตามสถานภาพนั้น"},{"text":"ข้อใดเป็นสถานภาพที่ได้มาภายหลัง","a":"เพศ","b":"อายุ","c":"ความเป็นพี่น้อง","d":"หัวหน้าห้อง","correct":3,"explain":"หัวหน้าห้องได้มาภายหลัง ส่วนเพศ อายุ ความเป็นพี่น้อง ได้มาโดยกำเนิด"},{"text":"“ประโยชน์ที่บุคคลได้รับ และกฎหมายรับรองคุ้มครอง” คือข้อใด","a":"สิทธิ","b":"เสรีภาพ","c":"หน้าที่","d":"บทบาท","correct":0,"explain":"สิทธิ คือ ประโยชน์ที่บุคคลได้รับและกฎหมายรับรองคุ้มครอง เช่น สิทธิได้รับการศึกษา สิทธิเลือกตั้ง"},{"text":"“นักเรียนตั้งใจเรียน” เป็นตัวอย่างของข้อใด","a":"สถานภาพ","b":"สิทธิ","c":"บทบาท","d":"เสรีภาพ","correct":2,"explain":"บทบาท คือ การปฏิบัติตามสิทธิและหน้าที่ตามสถานภาพ สไลด์ยกตัวอย่างว่า นักเรียนตั้งใจเรียน"},{"text":"ทำไมคนหนึ่งคนจึงมีได้หลายบทบาท","a":"เพราะมีได้หลายสถานภาพ","b":"เพราะกฎหมายบังคับไว้","c":"เพราะทุกคนอายุเท่ากัน","d":"เพราะไม่มีสิทธิเลือกเอง","correct":0,"explain":"สไลด์ระบุข้อสังเกตว่า คนหนึ่งคนมีได้หลายสถานภาพ จึงมีหลายบทบาท"},{"text":"ข้อใดเป็นการใช้เสรีภาพอย่างถูกต้อง","a":"โพสต์ข้อความต่อว่าเพื่อน","b":"แสดงความคิดเห็นอย่างสุภาพ","c":"พ่นสีบนกำแพงโรงเรียน","d":"ส่งข่าวลือให้เพื่อนต่อ","correct":1,"explain":"เสรีภาพ คือ ความอิสระในการคิด พูด หรือกระทำ โดยไม่ละเมิดผู้อื่นและไม่ขัดกฎหมาย การแสดงความคิดเห็นอย่างสุภาพจึงถูกต้อง ส่วนข้ออื่นละเมิดผู้อื่นหรือทำลายของส่วนรวม"},{"text":"ก่อนแชร์ข่าวในโซเชียล พลเมืองดีควรทำอย่างไร","a":"แชร์ทันทีให้เร็วที่สุด","b":"แชร์เฉพาะข่าวที่ตื่นเต้น","c":"ให้เพื่อนแชร์แทนตนเอง","d":"ตรวจสอบข่าวก่อนแชร์","correct":3,"explain":"แนวทางส่งเสริมพลเมืองดีด้านสื่อออนไลน์ คือ ตรวจสอบข่าวก่อนแชร์ ไม่โพสต์ข้อความที่ละเมิดหรือทำร้ายผู้อื่น"},{"text":"ห้องเรียนโหวตเลือกที่ทัศนศึกษา ฝ่ายที่แพ้โหวตควรทำอย่างไร","a":"ไม่ยอมไปร่วมกิจกรรม","b":"ยอมรับผลและร่วมกิจกรรม","c":"ขอโหวตใหม่จนกว่าจะชนะ","d":"ต่อว่าเพื่อนที่โหวตต่าง","correct":1,"explain":"ลักษณะของพลเมืองดีคือ ยอมรับเสียงข้างมาก เคารพเสียงข้างน้อย และใช้เหตุผลแก้ปัญหา ฝ่ายที่แพ้จึงควรยอมรับผลและร่วมกิจกรรม"},{"text":"จากแผนผังสรุป “รู้สถานภาพ → ทำตามบทบาท → ใช้สิทธิเสรีภาพ → ทำหน้าที่” พลเมืองดีคือคนแบบใด","a":"คนที่ใช้สิทธิเต็มที่ โดยไม่ต้องทำหน้าที่ใดๆ","b":"คนที่ทำทุกอย่างตามใจตนเอง ไม่สนใจผู้อื่น","c":"คนที่ทำตามบทบาท สิทธิ และหน้าที่อย่างรับผิดชอบ","d":"คนที่ไม่ยุ่งเกี่ยวกับกิจกรรมใดๆ ของสังคม","correct":2,"explain":"เมื่อรวมทุกขั้นในแผนผังเข้าด้วยกันจะตรงกับความหมายในสไลด์ คือ บุคคลที่ปฏิบัติตนตามสถานภาพ บทบาท สิทธิ เสรีภาพ และหน้าที่ด้วยความรับผิดชอบ"},{"text":"ข้อใดแสดงว่าทำหน้าที่ของปวงชนชาวไทยเรื่องการเลือกตั้งได้ดีที่สุด","a":"เลือกตั้งโดยคำนึงถึงส่วนรวม","b":"ไปเลือกตั้งเพราะได้รับเงิน","c":"ไม่ไปเลือกตั้งเพราะไม่ว่าง","d":"เลือกตามที่คนอื่นสั่งมา","correct":0,"explain":"หน้าที่ข้อ 7 คือ ไปใช้สิทธิเลือกตั้งอย่างอิสระโดยคำนึงถึงประโยชน์ส่วนรวม และข้อ 10 คือ ไม่สนับสนุนการทุจริต การรับเงินหรือทำตามคำสั่งผู้อื่นจึงไม่ถูกต้อง"}]},{"id":"exam-soc-02","name":"สังคม ม.2 · เรื่องที่ 2 สถาบันทางสังคม","subject":"สังคมศึกษา","unit":"หน่วยที่ 5 สถาบันทางสังคม · แผนที่ 2","questions":[{"text":"สถาบันใดเป็นสถาบันแรกที่อบรมเลี้ยงดูและสอนกฎเกณฑ์ของสังคม","a":"การศึกษา","b":"ครอบครัว","c":"ศาสนา","d":"สื่อสารมวลชน","correct":1,"explain":"ครอบครัวคือสถาบันแรก ให้กำเนิดสมาชิกใหม่ อบรมเลี้ยงดู ให้ความรักความอบอุ่น"},{"text":"สถาบันใดทำหน้าที่ผลิต แจกจ่าย และบริโภคสินค้าและบริการ","a":"เศรษฐกิจ","b":"การเมืองการปกครอง","c":"นันทนาการ","d":"การศึกษา","correct":0,"explain":"สถาบันเศรษฐกิจผลิต แจกจ่าย และบริโภคสินค้าและบริการ สร้างอาชีพและรายได้"},{"text":"ข้อใดเป็นองค์ประกอบของสถาบันทางสังคม","a":"ภูมิอากาศ","b":"ทรัพยากรแร่","c":"กลุ่มคน","d":"ความสูงของพื้นที่","correct":2,"explain":"องค์ประกอบของสถาบันทางสังคมมี 4 อย่าง คือ กลุ่มคน วัตถุประสงค์ แบบแผนการปฏิบัติ สถานภาพและบทบาท"},{"text":"คนไม่กล้าทำผิดเพราะยึดหลักศีลธรรม แสดงถึงหน้าที่ของสถาบันใด","a":"เศรษฐกิจ","b":"นันทนาการ","c":"สื่อสารมวลชน","d":"ศาสนา","correct":3,"explain":"สถาบันศาสนาเป็นที่ยึดเหนี่ยวจิตใจ และควบคุมพฤติกรรมด้วยหลักศีลธรรม"},{"text":"สถาบันทางสังคมมีความสำคัญอย่างไร","a":"ทำให้สังคมเป็นระเบียบเรียบร้อย","b":"ทำให้ทุกคนมีรายได้เท่ากัน","c":"ทำให้สังคมไม่ต้องมีกฎหมาย","d":"ทำให้คนไม่ต้องทำงานอีก","correct":0,"explain":"ความสำคัญของสถาบันทางสังคม คือ ตอบสนองความต้องการพื้นฐาน ควบคุมพฤติกรรม ทำให้สังคมเป็นระเบียบเรียบร้อย และถ่ายทอดวัฒนธรรม"},{"text":"“ระเบียบโรงเรียน” จัดเป็นองค์ประกอบข้อใดของสถาบันทางสังคม","a":"กลุ่มคน","b":"วัตถุประสงค์","c":"แบบแผนการปฏิบัติ","d":"สถานภาพและบทบาท","correct":2,"explain":"สไลด์ยกตัวอย่างแบบแผนการปฏิบัติ (บรรทัดฐานที่สมาชิกต้องปฏิบัติตาม) ว่า ระเบียบโรงเรียน"},{"text":"นักเรียนไปเล่นกีฬาที่สวนสาธารณะเพื่อผ่อนคลาย เกี่ยวข้องกับสถาบันใด","a":"การเมืองการปกครอง","b":"นันทนาการ","c":"ศาสนา","d":"การศึกษา","correct":1,"explain":"สถาบันนันทนาการให้ความสนุกสนาน ผ่อนคลาย ส่งเสริมสุขภาพกายและใจ"},{"text":"ครอบครัวไม่ดูแลบุตร จนเด็กออกจากโรงเรียนกลางคัน แสดงว่าอะไร","a":"สถาบันต่างๆ ทำงานแยกกัน ไม่เกี่ยวข้องกัน","b":"สถาบันหนึ่งบกพร่อง ส่งผลต่อสถาบันอื่น","c":"โรงเรียนเป็นสถาบันแรกที่เลี้ยงดูเด็ก","d":"ครอบครัวไม่ได้เป็นสถาบันทางสังคม","correct":1,"explain":"สไลด์ระบุว่าแต่ละสถาบันมีความสัมพันธ์กัน ถ้าสถาบันหนึ่งบกพร่องจะส่งผลต่อสถาบันอื่น ตัวอย่างคือ ครอบครัวไม่ดูแลบุตร ส่งผลให้เด็กออกจากโรงเรียนกลางคัน"},{"text":"ข้อใดสรุปความหมายของสถาบันทางสังคมแบบจำง่ายได้ถูกต้อง","a":"กลุ่มคน + อาคาร + เงินทุน","b":"กฎหมาย + ศาล + ตำรวจ","c":"ครู + นักเรียน + ห้องเรียน","d":"กลุ่มคน + กฎเกณฑ์ + บทบาท","correct":3,"explain":"สรุปเรื่องที่ 1 ในสไลด์ คือ สถาบันทางสังคม = กลุ่มคน + กฎเกณฑ์ + บทบาท ช่วยให้สมาชิกอยู่ร่วมกันได้"},{"text":"ปัญหาเด็กออกจากโรงเรียนกลางคัน ควรแก้อย่างไรจึงดีที่สุด","a":"ให้โรงเรียนแก้เพียงฝ่ายเดียว","b":"ปล่อยให้ครอบครัวแก้กันเอง","c":"ให้หลายสถาบันร่วมมือกันแก้","d":"รอให้ปัญหาหายไปเอง","correct":2,"explain":"สไลด์ระบุว่าการแก้ปัญหาสังคมต้องอาศัยหลายสถาบันร่วมมือกัน เพราะแต่ละสถาบันมีความสัมพันธ์และส่งผลต่อกัน"}]},{"id":"exam-soc-03","name":"สังคม ม.2 · เรื่องที่ 3 ความสัมพันธ์ของสถาบันทางสังคม","subject":"สังคมศึกษา","unit":"หน่วยที่ 5 สถาบันทางสังคม · แผนที่ 3","questions":[{"text":"ข้อใดเป็นลักษณะความสัมพันธ์ของสถาบันทางสังคม","a":"แยกกันทำงาน","b":"พึ่งพากัน","c":"แข่งขันกัน","d":"ไม่เกี่ยวข้องกัน","correct":1,"explain":"สถาบันทางสังคมสัมพันธ์กัน 3 แบบ คือ เชื่อมโยงกัน พึ่งพากัน และส่งผลกระทบต่อกัน (ปรับจากข้อทบทวนในสไลด์ให้เป็นคำถามเชิงบวก)"},{"text":"ครูเปรียบการทำงานร่วมกันของสถาบันทางสังคมว่าเหมือนสิ่งใด","a":"ฟันเฟือง","b":"ภูเขา","c":"แม่น้ำ","d":"ก้อนหิน","correct":0,"explain":"สไลด์เปรียบว่าสถาบันทางสังคมทำงานร่วมกันเหมือนฟันเฟือง ตัวหนึ่งหยุดหมุน ตัวอื่นทำงานไม่เต็มที่"},{"text":"ในงานประเพณียี่เป็ง ใครทำหน้าที่ดูแลความปลอดภัยและความสะอาด","a":"ครอบครัว","b":"วัด","c":"โรงเรียน","d":"เทศบาล","correct":3,"explain":"เทศบาลดูแลความปลอดภัยและความสะอาด งานสำเร็จได้เพราะทุกสถาบันร่วมมือกัน"},{"text":"“ผู้ปกครองตกงาน → ครอบครัวขาดรายได้ → เด็กออกจากโรงเรียน” เป็นความสัมพันธ์แบบใด","a":"เชื่อมโยงกัน","b":"พึ่งพากัน","c":"ส่งผลกระทบต่อกัน","d":"แข่งขันกัน","correct":2,"explain":"ถ้าสถาบันหนึ่งบกพร่อง จะกระทบต่อเนื่องเป็นโซ่ไปยังสถาบันอื่น จึงเป็นความสัมพันธ์แบบส่งผลกระทบต่อกัน"},{"text":"เด็กคนหนึ่งเป็นลูก เป็นนักเรียน และเป็นศาสนิกชนพร้อมกัน แสดงว่าสถาบันต่างๆ เป็นอย่างไร","a":"เชื่อมโยงกัน","b":"แยกออกจากกัน","c":"ต่อต้านกัน","d":"แข่งขันกัน","correct":0,"explain":"ความสัมพันธ์แบบเชื่อมโยงกัน คือ คนหนึ่งคนเป็นสมาชิกได้หลายสถาบันพร้อมกัน เช่น ลูก (ครอบครัว) นักเรียน (โรงเรียน) ศาสนิกชน (ศาสนา)"},{"text":"สถานประกอบการรับนักเรียนฝึกงานและให้ทุนการศึกษา เป็นความสัมพันธ์ระหว่างสถาบันใด","a":"ครอบครัว กับ ศาสนา","b":"เศรษฐกิจ กับ การศึกษา","c":"ศาสนา กับ นันทนาการ","d":"การศึกษา กับ ศาสนา","correct":1,"explain":"สไลด์ยกตัวอย่างความสัมพันธ์ เศรษฐกิจ ↕ การศึกษา ว่า โรงเรียนผลิตคนไปทำงาน และสถานประกอบการรับนักเรียนฝึกงานและให้ทุน"},{"text":"สื่อรายงานการทำงานของรัฐให้ประชาชนรู้ เป็นความสัมพันธ์ระหว่างสถาบันใด","a":"ครอบครัว กับ การศึกษา","b":"ศาสนา กับ เศรษฐกิจ","c":"สื่อสารมวลชน กับ การเมือง","d":"นันทนาการ กับ ครอบครัว","correct":2,"explain":"สไลด์ระบุว่า สื่อสารมวลชน ↕ การเมืองการปกครอง คือ สื่อรายงานการทำงานของรัฐให้ประชาชนรู้ และสะท้อนความเห็นของประชาชนไปยังรัฐ"},{"text":"ถ้าสถาบันหนึ่ง “หยุดหมุน” เหมือนฟันเฟือง จะเกิดอะไรขึ้น","a":"สถาบันอื่นทำงานได้ดีขึ้น","b":"สถาบันอื่นไม่ได้รับผลใดๆ","c":"สังคมไม่ต้องมีสถาบันอีก","d":"สถาบันอื่นทำงานไม่เต็มที่","correct":3,"explain":"สไลด์ระบุว่าทั้ง 7 สถาบันทำงานประสานกัน ถ้าตัวหนึ่งหยุดหมุน ตัวอื่นจะทำงานไม่เต็มที่"},{"text":"งานยี่เป็ง: ครอบครัวทำกระทง วัดจัดพิธี เทศบาลดูแลความปลอดภัย สรุปได้ว่าอย่างไร","a":"งานสำเร็จเพราะทุกสถาบันร่วมมือกัน","b":"งานสำเร็จเพราะวัดทำฝ่ายเดียว","c":"งานสำเร็จเพราะเทศบาลทำฝ่ายเดียว","d":"งานสำเร็จเพราะร้านค้ามีจำนวนมาก","correct":0,"explain":"เมื่อรวมหน้าที่ของแต่ละสถาบันในงานยี่เป็งเข้าด้วยกัน จะเห็นว่างานสำเร็จได้เพราะทุกสถาบันร่วมมือกัน ไม่ใช่สถาบันใดสถาบันหนึ่ง"},{"text":"ข้อใดเป็นการเป็นสมาชิกที่ดีของหลายสถาบันได้ดีที่สุด","a":"ตั้งใจเรียน แต่ไม่ช่วยงานบ้านเลย","b":"ร่วมงานชุมชน แต่ไม่ไปโรงเรียน","c":"ช่วยงานบ้าน ตั้งใจเรียน ร่วมงานชุมชน","d":"อยู่บ้านเล่นเกมเพียงอย่างเดียว","correct":2,"explain":"บทบาทของนักเรียนคือเป็นสมาชิกที่ดีในทุกสถาบันที่ตนสังกัด ได้แก่ ช่วยงานบ้าน ตั้งใจเรียน ร่วมกิจกรรมทางศาสนา และร่วมงานของชุมชน"}]},{"id":"exam-soc-04","name":"สังคม ม.2 · เรื่องที่ 4 การเปลี่ยนแปลงทางการเมืองไทย","subject":"สังคมศึกษา","unit":"หน่วยที่ 6 การเมืองการปกครอง · แผนที่ 4","questions":[{"text":"ผลของเหตุการณ์ 24 มิ.ย. 2475 คือข้อใด","a":"ตั้ง 12 กระทรวง","b":"มีรัฐธรรมนูญฉบับแรก","c":"ตั้ง กกต.","d":"นายกฯ ต้องเป็น ส.ส.","correct":1,"explain":"คณะราษฎรเปลี่ยนเป็นระบอบที่พระมหากษัตริย์อยู่ใต้รัฐธรรมนูญ ผลคือไทยมีรัฐธรรมนูญฉบับแรก"},{"text":"รัฐธรรมนูญ “ฉบับประชาชน” คือฉบับใด","a":"พ.ศ. 2475","b":"พ.ศ. 2517","c":"พ.ศ. 2560","d":"พ.ศ. 2540","correct":3,"explain":"รัฐธรรมนูญ พ.ศ. 2540 ได้ชื่อว่า “ฉบับประชาชน” ร่างโดย ส.ส.ร."},{"text":"เหตุการณ์ 14 ตุลาคม 2516 ผลคือข้อใด","a":"ตั้ง 12 กระทรวง","b":"ยกเลิกรัฐธรรมนูญ","c":"รัฐบาลลาออก","d":"เกิดการยึดอำนาจ","correct":2,"explain":"สไลด์ระบุว่ารัฐบาลลาออก และมีรัฐธรรมนูญ พ.ศ. 2517 ส่วนการยึดอำนาจเป็นผลของเหตุการณ์ 6 ตุลาคม 2519"},{"text":"แก้ให้นายกฯ ต้องเป็น ส.ส. เพราะปัญหาใด","a":"นายกฯ ไม่ได้มาจากเลือกตั้ง","b":"ไม่มีองค์กรอิสระตรวจสอบ","c":"ไม่มีกระทรวงดูแลประชาชน","d":"รัฐบาลอยู่ในตำแหน่งนานไป","correct":0,"explain":"ปี 2535 ประชาชนคัดค้านนายกฯ ที่ไม่ได้มาจากการเลือกตั้ง จึงแก้รัฐธรรมนูญให้นายกฯ ต้องเป็น ส.ส."},{"text":"องค์กรอิสระ เช่น กกต. มีไว้เพื่ออะไร","a":"ร่างรัฐธรรมนูญ","b":"เลือกนายกฯ","c":"ตรวจสอบอำนาจรัฐ","d":"ยึดอำนาจรัฐบาล","correct":2,"explain":"ผลของรัฐธรรมนูญ 2540 คือมีหน่วยตรวจสอบการใช้อำนาจรัฐ"},{"text":"เลือกหัวหน้าห้อง วิธีใดเป็นแบบสันติ","a":"ขู่เพื่อนให้เลือก","b":"ยึดตำแหน่งเอง","c":"ทะเลาะกันให้จบ","d":"ให้เพื่อนลงคะแนน","correct":3,"explain":"การเลือกตั้งและประชามติเป็นการเปลี่ยนแปลงแบบสันติ การลงคะแนนจึงเป็นแนวทางเดียวกัน"},{"text":"การปะทะและสลายการชุมนุม เป็นแบบใด","a":"แบบมีความสูญเสีย","b":"แบบสันติผ่านเลือกตั้ง","c":"แบบสันติผ่านประชามติ","d":"แบบสันติผ่านแก้กฎหมาย","correct":0,"explain":"สไลด์จัดการปะทะ สลายการชุมนุม และรัฐประหาร เป็นการเปลี่ยนแปลงที่เกิดความสูญเสีย"},{"text":"6 ต.ค. 2519 กับ พ.ศ. 2548–53 เหมือนกันอย่างไร","a":"ได้รัฐธรรมนูญฉบับแรก","b":"นายกฯ ต้องเป็น ส.ส.","c":"มีความสูญเสียและยึดอำนาจ","d":"ตั้งองค์กรอิสระ","correct":2,"explain":"ทั้งสองช่วงมีผู้เสียชีวิตและมีการยึดอำนาจ (2519 ยึดอำนาจเย็นวันเดียวกัน 2549 รัฐประหาร)"},{"text":"สรุปเส้นเวลา 8 เหตุการณ์ได้ข้อใด","a":"ไม่เคยเปลี่ยนแปลง","b":"มีทั้งสันติและสูญเสีย","c":"เกิดจากเลือกตั้งทุกครั้ง","d":"เกิดจากรัฐประหารทุกครั้ง","correct":1,"explain":"สไลด์แบ่งเป็นแบบสันติ (เลือกตั้ง ประชามติ แก้รัฐธรรมนูญ) และแบบสูญเสีย (ปะทะ สลายการชุมนุม รัฐประหาร)"},{"text":"เพื่อนทะเลาะกัน แก้อย่างไรเหมาะที่สุด","a":"ใช้กำลังให้จบ","b":"พูดคุยตามกติกา","c":"ส่งข้อความโจมตี","d":"รอคนอื่นตัดสิน","correct":1,"explain":"สไลด์สรุปว่าพลเมืองควรแก้ความขัดแย้งด้วยวิธีตามกฎหมายและการพูดคุย"}]},{"id":"exam-soc-05","name":"สังคม ม.2 · เรื่องที่ 5 การเลือกรับข้อมูลข่าวสาร","subject":"สังคมศึกษา","unit":"หน่วยที่ 6 การเมืองการปกครอง · แผนที่ 5","questions":[{"text":"ก่อนแชร์ข่าว ต้องทำตามข้อใด","a":"แชร์ → ตรวจสอบ → คิด","b":"คิด → แชร์ → ตรวจสอบ","c":"หยุดคิด → ตรวจสอบ → แชร์","d":"ตรวจสอบ → แชร์ → คิด","correct":2,"explain":"สไลด์สรุปว่า หยุดคิด → ตรวจสอบ → แล้วค่อยแชร์"},{"text":"แหล่งข่าวปฐมภูมิ คืออะไร","a":"ต้นทางโดยตรง","b":"ผู้รายงานต่อ","c":"ข้อความในแชต","d":"ภาพที่ตัดต่อ","correct":0,"explain":"แหล่งปฐมภูมิคือต้นทางโดยตรง เช่น ประกาศหน่วยงานรัฐ แถลงการณ์ เว็บไซต์ทางการ"},{"text":"ตรวจข่าว 4 ด่าน ด่านที่ 3 คืออะไร","a":"ที่มา","b":"วันที่","c":"เทียบข่าว","d":"หลักฐาน","correct":3,"explain":"ด่านที่ 1 ที่มา 2 วันที่ 3 หลักฐาน 4 เทียบข่าว"},{"text":"ข่าวปลอมต่างจากข่าวจริงอย่างไร","a":"มีหลักฐานชัดเจน","b":"ตั้งใจให้เข้าใจผิด","c":"บอกวันเวลาชัดเจน","d":"มาจากรัฐเสมอ","correct":1,"explain":"ข่าวปลอมเจตนาสร้างขึ้นให้เข้าใจผิด ส่วนข่าวจริงมีที่มา วันเวลา และหลักฐาน"},{"text":"ทำไมต้องเช็กวันที่ของข่าว","a":"เพราะวันที่ทำให้ข่าวตื่นเต้น","b":"เพราะข่าวใหม่ต้องจริงเสมอ","c":"เพราะวันที่บอกชื่อผู้เขียน","d":"เพราะอาจเป็นข่าวเก่าโพสต์ใหม่","correct":3,"explain":"ด่านวันที่ให้ตรวจว่าเป็นของเก่านำมาโพสต์ใหม่หรือไม่"},{"text":"ได้รับคลิปเร่งให้แชร์ ไม่รู้ที่มา ควรทำอย่างไร","a":"แชร์ต่อก่อน","b":"ตรวจที่มาก่อนแชร์","c":"เชื่อเพราะคนแชร์เยอะ","d":"ให้เพื่อนช่วยตัดสิน","correct":1,"explain":"มีสัญญาณเตือนข่าวปลอม จึงต้องหยุดคิดและตรวจสอบที่มาก่อนแชร์"},{"text":"อยากรู้ว่าภาพเป็นภาพเก่าหรือไม่ ใช้อะไรตรวจ","a":"ดูจำนวนยอดไลก์","b":"ถามความเห็นในคอมเมนต์","c":"ใช้ Google Image Search","d":"ดูว่าภาพสวยหรือไม่","correct":2,"explain":"สไลด์ให้ค้นภาพย้อนหลังด้วย Google Image Search หรือ TinEye"},{"text":"“ด่วน! สยดสยอง ต้องแชร์!” ไม่มีวันที่ ข้อใดคือสัญญาณเตือน","a":"เร่งแชร์ ปลุกอารมณ์","b":"บอกผู้เขียน มีหลักฐาน","c":"พาดหัวตรงกับเนื้อหา","d":"ที่มาชัด เทียบข่าวได้","correct":0,"explain":"สัญญาณเตือนข่าวปลอม: เร่งให้แชร์ ปลุกอารมณ์ ไม่มีวันเวลา ไม่ระบุผู้เขียน"},{"text":"ข้อใดรวม 4 ด่านตรวจข่าวครบ","a":"ที่มา วันที่ ยอดไลก์ ภาพ","b":"ที่มา หลักฐาน ยอดแชร์ ผู้เขียน","c":"ที่มา วันที่ หลักฐาน เทียบข่าว","d":"วันที่ ยอดไลก์ ภาพ สี","correct":2,"explain":"4 ด่านคือ ที่มา วันที่ หลักฐาน เทียบข่าว"},{"text":"ข่าว A ตรวจครบ ข่าว B ไม่มีผู้เขียน เร่งแชร์ ควรเชื่อข่าวใด","a":"ข่าว B เพราะเร่งให้แชร์","b":"ข่าว A เพราะผ่านการตรวจ","c":"เชื่อเท่ากันทั้งสองข่าว","d":"ไม่เชื่อทั้งสองข่าว","correct":1,"explain":"ข่าว A ผ่านทั้ง 4 ด่าน ส่วนข่าว B มีสัญญาณเตือนข่าวปลอม"}]},{"id":"exam-soc-06","name":"สังคม ม.2 · เรื่องที่ 6 กฎหมายและการตรากฎหมาย","subject":"สังคมศึกษา","unit":"หน่วยที่ 7 กฎหมาย · แผนที่ 6","questions":[{"text":"กฎหมายใดมีลำดับศักดิ์สูงสุด","a":"พระราชกฤษฎีกา","b":"รัฐธรรมนูญ","c":"กฎกระทรวง","d":"ข้อบัญญัติท้องถิ่น","correct":1,"explain":"รัฐธรรมนูญมีลำดับศักดิ์สูงสุด กฎหมายที่ศักดิ์ต่ำกว่าจะขัดกับรัฐธรรมนูญไม่ได้"},{"text":"กฎหมายแพ่งเป็นกฎหมายประเภทใด","a":"กฎหมายมหาชน","b":"กฎหมายท้องถิ่น","c":"กฎหมายเอกชน","d":"กฎกระทรวง","correct":2,"explain":"กฎหมายแพ่งเป็นกฎหมายเอกชน คือความสัมพันธ์ระหว่างเอกชนกับเอกชน"},{"text":"เมื่อพระมหากษัตริย์ทรงลงพระปรมาภิไธยแล้ว ต้องประกาศที่ใดจึงมีผลบังคับใช้","a":"หนังสือพิมพ์","b":"เว็บไซต์โรงเรียน","c":"ป้ายประกาศหมู่บ้าน","d":"ราชกิจจานุเบกษา","correct":3,"explain":"ขั้นสุดท้ายของการตรา พ.ร.บ. คือ ประกาศในราชกิจจานุเบกษา แล้วมีผลบังคับใช้ตามที่กำหนด"},{"text":"ข้อใดอธิบายความหมายของกฎหมายได้ถูกต้อง","a":"ข้อบังคับที่รัฐตราขึ้น ฝ่าฝืนต้องรับผล","b":"คำแนะนำที่จะทำตามหรือไม่ก็ได้","c":"ธรรมเนียมที่ครอบครัวตั้งขึ้นเอง","d":"กติกาเกมที่เพื่อนตกลงกันเอง","correct":0,"explain":"กฎหมาย คือ ข้อบังคับที่รัฐตราขึ้นเพื่อควบคุมความประพฤติของคนในสังคม ผู้ฝ่าฝืนต้องได้รับผลตามที่กฎหมายกำหนด"},{"text":"เพราะเหตุใดกฎกระทรวงจึงขัดกับรัฐธรรมนูญไม่ได้","a":"เพราะออกโดยประชาชนทั่วไป","b":"เพราะใช้เฉพาะในท้องถิ่นเท่านั้น","c":"เพราะมีศักดิ์ต่ำกว่ารัฐธรรมนูญ","d":"เพราะเป็นกฎหมายเอกชนทั้งหมด","correct":2,"explain":"ตามลำดับศักดิ์ กฎกระทรวงอยู่ต่ำกว่ารัฐธรรมนูญ และกฎหมายที่มีศักดิ์ต่ำกว่าจะขัดกับกฎหมายที่มีศักดิ์สูงกว่าไม่ได้"},{"text":"ประชาชนอยากเสนอร่างกฎหมายเรื่องสิทธิเสรีภาพ ต้องทำอย่างไร","a":"เข้าชื่อ 100 คน เสนอต่อนายอำเภอ","b":"โพสต์ในโซเชียลให้คนช่วยกันแชร์","c":"เขียนจดหมายถึงผู้อำนวยการโรงเรียน","d":"เข้าชื่อ 10,000 คนขึ้นไป เสนอประธานรัฐสภา","correct":3,"explain":"ผู้มีสิทธิเลือกตั้ง 10,000 คนขึ้นไป เข้าชื่อเสนอร่างกฎหมายต่อประธานรัฐสภาได้ เฉพาะเรื่องสิทธิเสรีภาพของประชาชนและหน้าที่ของรัฐ"},{"text":"ร่าง พ.ร.บ. ผ่านสภาผู้แทนราษฎรแล้ว ขั้นต่อไปต้องไปที่ใด","a":"วุฒิสภา","b":"ราชกิจจานุเบกษา","c":"ศาลฎีกา","d":"กระทรวงศึกษาธิการ","correct":0,"explain":"ขั้นตอนการตรา พ.ร.บ. คือ เสนอร่าง → สภาผู้แทนราษฎร → วุฒิสภา → นายกรัฐมนตรีนำขึ้นทูลเกล้าฯ → ทรงลงพระปรมาภิไธย → ประกาศราชกิจจานุเบกษา"},{"text":"ถ้าสังคมไม่มีกฎหมาย จะเกิดผลอย่างไรมากที่สุด","a":"ทุกคนอยู่อย่างสงบสุขกว่าเดิม","b":"เกิดความวุ่นวาย ข้อพิพาทยุติไม่ได้","c":"ทุกคนได้รับความเป็นธรรมเท่ากัน","d":"สิทธิเสรีภาพได้รับการคุ้มครองมากขึ้น","correct":1,"explain":"กฎหมายมีความสำคัญ 4 ข้อ คือ รักษาความสงบเรียบร้อย คุ้มครองสิทธิเสรีภาพ ระงับข้อพิพาท และสร้างความเป็นธรรม ถ้าไม่มีกฎหมายจึงขาดสิ่งเหล่านี้ ส่วนตัวเลือกอื่นคือผลของการมีกฎหมาย"},{"text":"ข้อใดเรียงขั้นตอนการตรา พ.ร.บ. ได้ถูกต้อง","a":"วุฒิสภา → เสนอร่าง → สภาผู้แทนฯ → ประกาศใช้","b":"ประกาศใช้ → เสนอร่าง → สภาผู้แทนฯ → วุฒิสภา","c":"เสนอร่าง → สภาผู้แทนฯ → วุฒิสภา → ประกาศใช้","d":"เสนอร่าง → ประกาศใช้ → วุฒิสภา → สภาผู้แทนฯ","correct":2,"explain":"เมื่อนำทั้ง 6 ด่านมาเรียงกัน จะเป็น เสนอร่าง → สภาผู้แทนราษฎร (3 วาระ) → วุฒิสภา → นายกฯ ทูลเกล้าฯ → ทรงลงพระปรมาภิไธย → ประกาศราชกิจจานุเบกษา"},{"text":"นักเรียนจะมีส่วนร่วมในการตรากฎหมายอย่างไรจึงเหมาะสมที่สุด","a":"ไม่สนใจเพราะเป็นเรื่องผู้ใหญ่","b":"แสดงความเห็นผ่านการรับฟังความคิดเห็น","c":"แชร์ข่าวลือเรื่องร่างกฎหมาย","d":"ไม่ทำตามกฎหมายที่ตนไม่ชอบ","correct":1,"explain":"สไลด์ระบุว่าประชาชนมีส่วนร่วมได้โดยแสดงความเห็นต่อร่างกฎหมายผ่านการรับฟังความคิดเห็นและติดตามข่าวสาร ส่วนข้ออื่นเป็นการละเลยหรือฝ่าฝืน"}]},{"id":"exam-soc-07","name":"สังคม ม.2 · เรื่องที่ 7 กฎหมายเกี่ยวกับตนเองและครอบครัว","subject":"สังคมศึกษา","unit":"หน่วยที่ 7 กฎหมาย · แผนที่ 7","questions":[{"text":"บุคคลจะบรรลุนิติภาวะเมื่ออายุเท่าใด","a":"7 ปีบริบูรณ์","b":"15 ปีบริบูรณ์","c":"20 ปีบริบูรณ์","d":"25 ปีบริบูรณ์","correct":2,"explain":"บุคคลบรรลุนิติภาวะเมื่ออายุ 20 ปีบริบูรณ์ หรือสมรสโดยชอบด้วยกฎหมาย"},{"text":"บุตรฟ้องบิดามารดาของตนเองไม่ได้ เรียกว่าคดีอะไร","a":"คดีอุทลุม","b":"คดีแพ่ง","c":"คดีอาญา","d":"คดีปกครอง","correct":0,"explain":"คดีอุทลุม คือ บุตรฟ้องบุพการีของตนไม่ได้ แต่ขอให้อัยการฟ้องแทนได้"},{"text":"การทำบัตรประจำตัวประชาชน ทำได้ที่ใด","a":"โรงพยาบาลจังหวัด","b":"ที่ทำการไปรษณีย์","c":"สาขาธนาคาร","d":"ที่ว่าการอำเภอ","correct":3,"explain":"สไลด์ระบุว่าทำบัตรประชาชนได้ที่ที่ว่าการอำเภอหรือสำนักงานเขต"},{"text":"ผู้เยาว์จะทำนิติกรรม เช่น ทำสัญญา ต้องทำอย่างไรก่อน","a":"ขอความยินยอมจากเพื่อนสนิท","b":"ขอความยินยอมจากบิดามารดา","c":"แจ้งครูประจำชั้นก่อน","d":"ทำได้ทันทีไม่ต้องขอใคร","correct":1,"explain":"ผู้เยาว์ทำนิติกรรมต้องได้รับความยินยอมจากผู้แทนโดยชอบธรรม เช่น บิดามารดา ก่อน มิฉะนั้นเป็นโมฆียะ"},{"text":"ของหมั้นกับสินสอดต่างกันอย่างไร","a":"ของหมั้นให้บิดามารดา สินสอดให้ผู้รับหมั้น","b":"ทั้งสองอย่างมอบให้ผู้รับหมั้นเท่านั้น","c":"ของหมั้นให้ผู้รับหมั้น สินสอดให้บิดามารดา","d":"ทั้งสองอย่างมอบให้ฝ่ายผู้หมั้นเท่านั้น","correct":2,"explain":"ของหมั้นมอบให้ผู้รับหมั้น ส่วนสินสอดมอบให้บิดามารดาหรือผู้ปกครองของผู้รับหมั้น"},{"text":"เด็กชายเอ อายุ 14 ปี ต้องมีบัตรประจำตัวประชาชนหรือไม่","a":"ต้องมี เพราะอายุเกิน 7 ปีแล้ว","b":"ยังไม่ต้องมี จนกว่าอายุ 15 ปี","c":"ยังไม่ต้องมี จนกว่าอายุ 18 ปี","d":"ยังไม่ต้องมี จนกว่าอายุ 20 ปี","correct":0,"explain":"ผู้มีสัญชาติไทยอายุ 7 ปีบริบูรณ์ถึง 70 ปีบริบูรณ์ที่มีชื่อในทะเบียนบ้านต้องมีบัตรประชาชน เด็กชายเออายุ 14 ปีจึงต้องมีบัตร"},{"text":"สามีภรรยาตกลงหย่ากันด้วยความยินยอม ต้องทำอย่างไร","a":"บอกเพื่อนบ้านให้รับรู้ก็พอ","b":"ทำหนังสือ มีพยาน 2 คน และจดทะเบียนหย่า","c":"แยกบ้านกันอยู่ก็ถือว่าหย่าแล้ว","d":"ประกาศเรื่องหย่าทางโซเชียลมีเดีย","correct":1,"explain":"การหย่าโดยความยินยอมต้องทำเป็นหนังสือ มีพยาน 2 คน และจดทะเบียนหย่า"},{"text":"ผู้เยาว์ซื้ออาหารกินเองได้โดยไม่ต้องขอบิดามารดา เพราะเหตุใด","a":"เพราะผู้เยาว์บรรลุนิติภาวะแล้ว","b":"เพราะอาหารไม่ใช่สินค้า","c":"เพราะร้านค้าอยู่ใกล้บ้าน","d":"เพราะเป็นสิ่งจำเป็นในการเลี้ยงชีพ","correct":3,"explain":"ข้อยกเว้นที่ผู้เยาว์ทำเองได้ ได้แก่ นิติกรรมที่เป็นสิ่งจำเป็นในการเลี้ยงชีพตามสมควร การซื้ออาหารกินจึงทำได้"},{"text":"ข้อใดสรุปหน้าที่ตามกฎหมายระหว่างบิดามารดากับบุตรได้ถูกต้อง","a":"บิดามารดามีหน้าที่ฝ่ายเดียว","b":"บุตรมีหน้าที่ฝ่ายเดียว","c":"ต่างฝ่ายต่างมีหน้าที่อุปการะกัน","d":"ไม่มีใครมีหน้าที่ต่อกัน","correct":2,"explain":"เมื่อรวมหน้าที่ทั้งสองฝ่าย จะเห็นว่าบิดามารดาต้องอุปการะเลี้ยงดูและให้การศึกษาแก่บุตร ส่วนบุตรต้องอุปการะเลี้ยงดูบิดามารดา จึงมีหน้าที่ต่อกันทั้งสองฝ่าย"},{"text":"ข้อใดเป็นการใช้อำนาจปกครองของบิดามารดาที่เหมาะสมที่สุด","a":"ว่ากล่าวสั่งสอนลูกตามสมควร","b":"ทำร้ายร่างกายลูกเมื่อทำผิด","c":"ใช้คำพูดทำร้ายจิตใจลูก","d":"ให้ลูกทำงานหนักเกินกำลัง","correct":0,"explain":"บิดามารดาใช้อำนาจปกครองได้ เช่น ว่ากล่าวสั่งสอนตามสมควร และให้บุตรทำการงานตามสมควรแก่ความสามารถ แต่ตั้งแต่ปี 2568 ห้ามทารุณหรือใช้ความรุนแรงต่อร่างกายและจิตใจ"}]},{"id":"exam-soc-08","name":"สังคม ม.2 · เรื่องที่ 8 กฎหมายเกี่ยวกับชุมชน","subject":"สังคมศึกษา","unit":"หน่วยที่ 7 กฎหมาย · แผนที่ 8","questions":[{"text":"ภาษีมูลค่าเพิ่ม (VAT) เก็บจากสิ่งใด","a":"เงินเดือนของลูกจ้าง","b":"การซื้อสินค้าและบริการ","c":"ที่ดินและบ้าน","d":"การฝากเงินในธนาคาร","correct":1,"explain":"ภาษีมูลค่าเพิ่มเก็บจากการซื้อสินค้าและบริการ ผู้ซื้อจ่ายผ่านราคาสินค้า"},{"text":"ภาษีที่ดินและสิ่งปลูกสร้าง ใครเป็นผู้จัดเก็บ","a":"องค์กรปกครองส่วนท้องถิ่น","b":"ผู้อำนวยการโรงเรียน","c":"คณะกรรมการวัดในหมู่บ้าน","d":"บริษัทเอกชนในจังหวัด","correct":0,"explain":"องค์กรปกครองส่วนท้องถิ่นเป็นผู้จัดเก็บภาษีที่ดินและสิ่งปลูกสร้าง แล้วนำไปพัฒนาท้องถิ่น"},{"text":"พ.ร.บ.สิ่งแวดล้อมฯ 2535 กำหนดเรื่องใด","a":"อายุขั้นต่ำของลูกจ้างในโรงงาน","b":"อัตราภาษีมูลค่าเพิ่มของสินค้า","c":"มาตรฐานคุณภาพน้ำ อากาศ และเสียง","d":"อายุที่ต้องทำบัตรประจำตัวประชาชน","correct":2,"explain":"พ.ร.บ.สิ่งแวดล้อมฯ 2535 กำหนดมาตรฐานคุณภาพน้ำ อากาศ และเสียง และผู้ก่อมลพิษต้องรับผิดชอบ"},{"text":"รัฐนำเงินภาษีไปใช้ทำอะไร","a":"แจกให้เจ้าหน้าที่นำไปใช้ส่วนตัว","b":"เก็บไว้เฉยๆ โดยไม่นำไปใช้อะไร","c":"ซื้อของขวัญคืนให้ผู้เสียภาษีทุกคน","d":"จัดบริการสาธารณะ เช่น ถนน โรงเรียน","correct":3,"explain":"ภาษีอากรคือเงินที่ประชาชนและธุรกิจเสียให้รัฐ รัฐนำไปจัดบริการสาธารณะ เช่น ถนน โรงเรียน สถานีอนามัย และรักษาป่า"},{"text":"การสั่งเมนูเนื้อสัตว์ป่าคุ้มครองมากิน มีความผิดหรือไม่","a":"ไม่ผิด เพราะเป็นแค่ผู้สั่งอาหาร","b":"ผิด เพราะนับเป็นการครอบครองซาก","c":"ไม่ผิด ถ้าร้านเป็นผู้ล่าสัตว์เอง","d":"ผิด เฉพาะเมื่อกินไม่หมด","correct":1,"explain":"ผู้สั่งเมนูเนื้อสัตว์ป่าคุ้มครองนับเป็นการครอบครองซาก มีโทษจำคุกไม่เกิน 5 ปี หรือปรับไม่เกิน 500,000 บาท หรือทั้งจำทั้งปรับ"},{"text":"ซื้อสมุดราคา 100 บาท บวกภาษีมูลค่าเพิ่ม 7% ต้องจ่ายรวมกี่บาท","a":"93 บาท","b":"100 บาท","c":"107 บาท","d":"170 บาท","correct":2,"explain":"VAT 7% ของ 100 บาท = 7 บาท รวมจ่าย 100 + 7 = 107 บาท"},{"text":"เมื่อไปเที่ยวอุทยานแห่งชาติ ข้อใดปฏิบัติถูกต้องตามกฎหมาย","a":"เก็บกล้วยไม้ป่ากลับบ้าน","b":"นำอุปกรณ์ล่าสัตว์เข้าไป","c":"ขีดเขียนชื่อบนก้อนหิน","d":"ชมธรรมชาติโดยไม่รบกวนสัตว์","correct":3,"explain":"พ.ร.บ.อุทยานฯ 2562 ห้ามล่าหรือรบกวนสัตว์ป่า นำอาวุธหรืออุปกรณ์ล่าสัตว์เข้าไป เก็บหาของป่า และทำลายสภาพธรรมชาติ"},{"text":"โรงงานปล่อยน้ำเสียเกินมาตรฐานลงคลอง ข้อใดถูกต้อง","a":"ผิด พ.ร.บ.ป่าไม้ ชาวบ้านต้องรับผิดชอบ","b":"ผิด พ.ร.บ.สิ่งแวดล้อม โรงงานต้องรับผิดชอบ","c":"ไม่ผิด เพราะคลองเป็นของทุกคน","d":"ผิด พ.ร.บ.อุทยาน นักท่องเที่ยวต้องรับผิดชอบ","correct":1,"explain":"พ.ร.บ.สิ่งแวดล้อมฯ 2535 ห้ามปล่อยน้ำเสียเกินมาตรฐานลงแหล่งน้ำสาธารณะ และผู้ก่อมลพิษต้องรับผิดชอบ"},{"text":"การทำตามกฎหมายอนุรักษ์และเสียภาษีถูกต้อง ส่งผลต่อชุมชนอย่างไร","a":"มีทรัพยากรและบริการสาธารณะที่ดียั่งยืน","b":"ชุมชนเสียภาษีน้อยลงเรื่อยๆ ทุกปี","c":"ชุมชนไม่ต้องมีกฎหมายใดๆ อีกต่อไป","d":"ชุมชนตัดไม้ในป่าได้มากขึ้นกว่าเดิม","correct":0,"explain":"สไลด์สรุปข้อคิดว่า การปฏิบัติตามกฎหมายอนุรักษ์ธรรมชาติและการเสียภาษีให้ถูกต้อง ช่วยให้ชุมชนมีทรัพยากรและบริการสาธารณะที่ดีอย่างยั่งยืน"},{"text":"นายแดงมีเงินได้ เขาควรทำอย่างไรเรื่องภาษีเงินได้จึงเหมาะสมที่สุด","a":"ไม่ยื่นแบบเพราะไม่มีใครตรวจ","b":"ซ่อนรายได้เพื่อเสียภาษีน้อยลง","c":"รอให้เจ้าหน้าที่มาเตือนก่อน","d":"ยื่นแบบภายในเดือนมีนาคมของปีถัดไป","correct":3,"explain":"ภาษีเงินได้บุคคลธรรมดาเก็บจากผู้มีเงินได้ ต้องยื่นแบบภายในเดือนมีนาคมของปีถัดไป การทำตามกฎหมายช่วยให้รัฐมีเงินจัดบริการสาธารณะ"}]},{"id":"exam-soc-09","name":"สังคม ม.2 · เรื่องที่ 9 กฎหมายเกี่ยวกับประเทศ","subject":"สังคมศึกษา","unit":"หน่วยที่ 7 กฎหมาย · แผนที่ 9","questions":[{"text":"นายจ้างห้ามจ้างเด็กอายุต่ำกว่ากี่ปี","a":"13 ปี","b":"15 ปี","c":"18 ปี","d":"20 ปี","correct":1,"explain":"ห้ามจ้างเด็กอายุต่ำกว่า 15 ปี ส่วนเด็ก 15–18 ปีห้ามทำงาน 22.00–06.00 น. และงานอันตราย"},{"text":"ถูกนายจ้างเอาเปรียบ ควรแจ้งหน่วยงานใด","a":"สถานีอนามัยประจำตำบล","b":"ห้องสมุดประชาชนในชุมชน","c":"กรมสวัสดิการและคุ้มครองแรงงาน","d":"ที่ทำการไปรษณีย์ในจังหวัด","correct":2,"explain":"ถูกเอาเปรียบให้แจ้งกรมสวัสดิการและคุ้มครองแรงงาน สายด่วน 1546"},{"text":"ผู้บริหารราชการส่วนท้องถิ่น เช่น เทศบาล อบต. มาจากที่ใด","a":"การแต่งตั้งจากกระทรวง","b":"การสืบทอดทางสายเลือด","c":"การจับสลาก","d":"การเลือกตั้ง","correct":3,"explain":"การบริหารราชการส่วนท้องถิ่น (อบจ. เทศบาล อบต.) มีผู้บริหารที่มาจากการเลือกตั้ง"},{"text":"การบริหารราชการส่วนภูมิภาค (จังหวัด อำเภอ) มีหน้าที่อย่างไร","a":"ออกกฎหมายแทนรัฐสภาทั้งหมด","b":"เป็นตัวแทนของส่วนกลางในพื้นที่","c":"ดูแลงานของทั้งประเทศโดยตรง","d":"เก็บขยะและดูแลน้ำประปาในเมือง","correct":1,"explain":"ส่วนภูมิภาค คือ จังหวัดและอำเภอ เป็นตัวแทนของส่วนกลางในพื้นที่ เช่น ทำบัตรประชาชนที่อำเภอ"},{"text":"พ.ร.บ.คุ้มครองแรงงาน กำหนดเรื่องใด","a":"มาตรฐานขั้นต่ำที่นายจ้างต้องทำต่อลูกจ้าง","b":"ราคาสินค้าที่ร้านค้าทุกร้านต้องขาย","c":"จำนวนภาษีที่ประชาชนทุกคนต้องจ่าย","d":"เวลาเปิดและปิดของโรงเรียนทุกแห่ง","correct":0,"explain":"พ.ร.บ.คุ้มครองแรงงาน พ.ศ. 2541 กำหนดมาตรฐานขั้นต่ำที่นายจ้างต้องปฏิบัติต่อลูกจ้าง"},{"text":"ถนนชำรุด ขยะไม่มีคนเก็บ ควรติดต่อการบริหารราชการส่วนใด","a":"ส่วนกลาง เช่น กระทรวง","b":"ส่วนภูมิภาค เช่น จังหวัด","c":"ส่วนท้องถิ่น เช่น เทศบาล","d":"ศาล เช่น ศาลฎีกา","correct":2,"explain":"ส่วนท้องถิ่น เช่น เทศบาล อบต. ดูแลถนน ขยะ น้ำประปา"},{"text":"น้องอายุ 16 ปีทำงานร้านกาแฟ นายจ้างให้ทำงานถึง 23.00 น. ถูกต้องหรือไม่","a":"ถูกต้อง เพราะอายุเกิน 15 ปีแล้ว","b":"ไม่ถูกต้อง เพราะเลยเวลา 22.00 น.","c":"ถูกต้อง ถ้านายจ้างจ่ายเงินเพิ่ม","d":"ไม่ถูกต้อง เพราะเด็กห้ามทำงานทุกกรณี","correct":1,"explain":"เด็กอายุ 15–18 ปี ห้ามทำงานช่วง 22.00–06.00 น. การทำงานถึง 23.00 น. จึงผิดกฎหมาย แต่เด็กอายุ 15 ปีขึ้นไปทำงานได้ในเวลาที่กำหนด"},{"text":"ลูกจ้างทำงานครบ 1 ปี แต่นายจ้างไม่ให้วันพักผ่อนประจำปีเลย ข้อใดถูกต้อง","a":"นายจ้างทำถูก เพราะเป็นสิทธิ์นายจ้าง","b":"นายจ้างทำถูก ถ้าจ่ายเงินเดือนตรงเวลา","c":"นายจ้างทำผิด ลูกจ้างต้องได้ 120 วัน","d":"นายจ้างทำผิด ลูกจ้างต้องได้อย่างน้อย 6 วัน","correct":3,"explain":"กฎหมายกำหนดวันพักผ่อนประจำปีไม่น้อยกว่า 6 วันเมื่อทำงานครบ 1 ปี ส่วน 120 วันเป็นวันลาคลอดของลูกจ้างหญิง"},{"text":"การรู้สิทธิแรงงานและรู้ว่าหน่วยงานใดรับผิดชอบเรื่องใด ช่วยเราอย่างไร","a":"ทำให้ไม่ต้องทำงานหนักอีกต่อไปเลย","b":"ทำให้ได้ค่าจ้างสูงกว่าคนอื่นทุกคน","c":"ป้องกันถูกเอาเปรียบ และแก้ปัญหาได้ถูกที่","d":"ทำให้ไม่ต้องเสียภาษีเงินได้อีกต่อไป","correct":2,"explain":"สไลด์สรุปข้อคิดว่า รู้สิทธิแรงงานช่วยป้องกันการถูกเอาเปรียบ และรู้ว่าหน่วยงานใดรับผิดชอบเรื่องใด ช่วยให้แก้ปัญหาได้รวดเร็วและถูกต้อง"},{"text":"ภรรยาของคุณสมชายคลอดลูก คุณสมชายควรทำอย่างไรจึงเหมาะสมที่สุดตามกฎหมาย","a":"ลาไปช่วยภรรยาตามสิทธิ ไม่เกิน 15 วัน","b":"ลาออกจากงานทันที","c":"ขาดงานโดยไม่แจ้งนายจ้าง","d":"ทำงานตามปกติเพราะไม่มีสิทธิลา","correct":0,"explain":"พ.ร.บ.คุ้มครองแรงงาน (ฉบับที่ 9 พ.ศ. 2568) ให้ลูกจ้างชายลาช่วยภรรยาคลอดได้ไม่เกิน 15 วัน การใช้สิทธินี้จึงเหมาะสมที่สุด"}]},{"id":"exam-soc-10","name":"สังคม ม.2 · เรื่องที่ 10 วัฒนธรรมเอเชีย","subject":"สังคมศึกษา","unit":"หน่วยที่ 8 วัฒนธรรม · แผนที่ 10","questions":[{"text":"ประเทศใดทักทายด้วยการพนมมือกล่าว “นมัสเต”","a":"ญี่ปุ่น","b":"จีน","c":"อินเดีย","d":"ซาอุดีอาระเบีย","correct":2,"explain":"ชาวอินเดียพนมมือกล่าว “นมัสเต” ซึ่งคล้ายการไหว้ของไทย"},{"text":"ชุดประจำชาติของเกาหลีใต้คือชุดใด","a":"กิโมโน","b":"ฮันบก","c":"กี่เพ้า","d":"ส่าหรี","correct":1,"explain":"เกาหลีใต้ = ชุดฮันบก ส่วนกิโมโนเป็นของญี่ปุ่น กี่เพ้าของจีน และส่าหรีของอินเดีย"},{"text":"ข้อใดเป็นข้อห้ามด้านอาหารของชาวซาอุดีอาระเบีย","a":"ไม่กินข้าวทุกชนิด","b":"ไม่ใช้ตะเกียบกินข้าว","c":"ไม่กินอินทผลัมเลย","d":"ไม่กินหมูและแอลกอฮอล์","correct":3,"explain":"ชาวซาอุดีอาระเบียนับถือศาสนาอิสลาม จึงไม่กินหมูและไม่ดื่มแอลกอฮอล์"},{"text":"ชาวซาอุดีอาระเบียละหมาดวันละ 5 เวลา เพราะเหตุใด","a":"เพราะนับถือศาสนาอิสลาม","b":"เพราะนับถือศาสนาฮินดู","c":"เพราะนับถือลัทธิชินโต","d":"เพราะนับถือลัทธิขงจื๊อ","correct":0,"explain":"ชาวซาอุดีอาระเบียนับถือศาสนาอิสลาม ซึ่งละหมาดวันละ 5 เวลา ถือศีลอดเดือนรอมฎอน และประกอบพิธีฮัจญ์"},{"text":"ข้อใดเป็นความคล้ายคลึงระหว่างวัฒนธรรมไทยกับอินเดีย","a":"ไทยกับอินเดียสวมส่าหรีเหมือนกัน","b":"ไทยกับอินเดียกินข้าวด้วยตะเกียบ","c":"ไทยรับพระพุทธศาสนามาจากอินเดีย","d":"ไทยกับอินเดียถือศีลอดรอมฎอน","correct":2,"explain":"สไลด์ระบุความคล้ายว่า พระพุทธศาสนามาจากอินเดีย รามเกียรติ์มาจากรามายณะ และการไหว้คล้ายนมัสเต"},{"text":"ไปเที่ยวบ้านเพื่อนชาวญี่ปุ่น ก่อนเข้าบ้านควรทำอย่างไร","a":"สวมรองเท้าเข้าบ้านได้เลย","b":"ถอดรองเท้าก่อนเข้าบ้าน","c":"กล่าวคำว่าอัสลามุอะลัยกุม","d":"พนมมือกล่าวคำว่านมัสเต","correct":1,"explain":"ประเพณีของญี่ปุ่นคือ ถอดรองเท้าก่อนเข้าบ้าน และทักทายด้วยการโค้งคำนับ"},{"text":"ยื่นของให้ผู้ใหญ่ชาวเกาหลีใต้ ควรทำอย่างไร","a":"โยนให้รับเอง","b":"วางไว้บนพื้น","c":"ยื่นด้วยมือเดียว","d":"ยื่นด้วยสองมือ","correct":3,"explain":"ชาวเกาหลีใต้ทักทายด้วยการโค้งคำนับ และยื่นของด้วยสองมือให้ผู้ใหญ่"},{"text":"เพื่อนชาวอินเดียส่วนใหญ่ไม่กินเนื้อวัว เพราะเหตุใด","a":"เพราะเนื้อวัวในอินเดียราคาแพงมาก","b":"เพราะในประเทศอินเดียไม่มีวัวเลย","c":"เพราะชาวอินเดียกินแต่ซูชิกับข้าว","d":"เพราะฮินดูถือว่าวัวศักดิ์สิทธิ์","correct":3,"explain":"ชาวอินเดียส่วนใหญ่นับถือศาสนาฮินดู ซึ่งถือว่าวัวเป็นสัตว์ศักดิ์สิทธิ์ ชาวฮินดูจึงไม่กินเนื้อวัว"},{"text":"ข้อใดสรุปความคล้ายของไทย ญี่ปุ่น เกาหลีใต้ และจีนได้ถูกต้อง","a":"กินข้าวเป็นอาหารหลัก","b":"ใช้ตะเกียบเหมือนกันทุกประเทศ","c":"สวมชุดประจำชาติแบบเดียวกัน","d":"นับถือศาสนาอิสลามเหมือนกัน","correct":0,"explain":"เมื่อเทียบข้อมูลทั้ง 4 ประเทศ จะพบว่ากินข้าวเป็นอาหารหลักเหมือนกัน ส่วนไทยใช้ช้อนส้อม ไม่ได้ใช้ตะเกียบ และชุดกับศาสนาต่างกัน"},{"text":"เมื่อเห็นวัฒนธรรมที่ต่างจากไทย ข้อใดเป็นความคิดที่เหมาะสมที่สุด","a":"วัฒนธรรมไทยดีที่สุด ชาติอื่นผิด","b":"ควรเลิกวัฒนธรรมไทยแล้วใช้ของต่างชาติ","c":"วัฒนธรรมไม่มีถูกผิด ควรเรียนรู้กัน","d":"ไม่ต้องสนใจวัฒนธรรมของชาติอื่น","correct":2,"explain":"สไลด์สรุปข้อคิดว่า วัฒนธรรมไม่มีถูกหรือผิด การเรียนรู้ความเหมือนและความต่างช่วยให้ภูมิใจในความเป็นไทยและอยู่ร่วมกับผู้อื่นอย่างเข้าใจ"}]},{"id":"exam-soc-11","name":"สังคม ม.2 · เรื่องที่ 11 วัฒนธรรมสู่ความเข้าใจอันดี","subject":"สังคมศึกษา","unit":"หน่วยที่ 8 วัฒนธรรม · แผนที่ 11","questions":[{"text":"คนไทยถือว่าส่วนใดของร่างกายเป็นของสูง ไม่ควรแตะของผู้อื่น","a":"เท้า","b":"มือ","c":"ศีรษะ","d":"ไหล่","correct":2,"explain":"คนไทยถือว่าศีรษะเป็นของสูง ไม่ควรแตะศีรษะผู้อื่น"},{"text":"ข้อใดเป็น “ความเหมือน” ที่ช่วยเชื่อมความสัมพันธ์","a":"อาหารต้องห้าม","b":"การเคารพผู้อาวุโส","c":"วิธีการทักทาย","d":"ศาสนาที่นับถือ","correct":1,"explain":"สไลด์ระบุว่าความเหมือนช่วยเชื่อมความสัมพันธ์ เช่น การเคารพผู้อาวุโส การกินข้าว พระพุทธศาสนา ส่วนศาสนา อาหารต้องห้าม การทักทาย เป็นความต่าง"},{"text":"การใช้เท้าชี้ของหรือชี้คน คนไทยมองว่าอย่างไร","a":"ไม่สุภาพ","b":"สุภาพมาก","c":"เป็นมงคล","d":"แสดงความเคารพ","correct":0,"explain":"คนไทยถือว่าเท้าเป็นของต่ำ การใช้เท้าชี้ของหรือชี้คนจึงไม่สุภาพ"},{"text":"ชาวจีนบางส่วนไม่นิยมรับนาฬิกาเป็นของขวัญ เพราะเหตุใด","a":"เพราะนาฬิกามีราคาแพงเกินไป","b":"เพราะชาวจีนไม่ชอบดูเวลาเลย","c":"เพราะเสียงคล้ายคำว่า “ส่งคนตาย”","d":"เพราะนาฬิกาถือเป็นของต่ำ","correct":2,"explain":"สไลด์ระบุว่าชาวจีนบางส่วนถือว่าการให้นาฬิกาไม่เป็นมงคล เพราะคำว่า “ให้นาฬิกา” เสียงคล้าย “ส่งคนตาย”"},{"text":"โค้งคำนับ ไหว้ และนมัสเต เหมือนกันตรงที่ใด","a":"ใช้มือข้างเดียว","b":"แสดงความเคารพ","c":"แสดงความโกรธ","d":"ใช้เฉพาะในงานศพ","correct":1,"explain":"โค้งคำนับ (ญี่ปุ่น) ไหว้ (ไทย) นมัสเต (อินเดีย) ต่างท่าทาง แต่เหมือนกันที่แสดงความเคารพ"},{"text":"เมื่อส่งของให้ชาวอินเดียหรือชาวซาอุดีอาระเบีย ควรทำอย่างไร","a":"ส่งด้วยมือซ้าย","b":"ใช้เท้าดันไปให้","c":"วางไว้ที่พื้น","d":"ส่งด้วยมือขวา","correct":3,"explain":"ชาวอินเดียและซาอุดีอาระเบียถือว่ามือซ้ายไม่สะอาด จึงควรใช้มือขวา"},{"text":"กินข้าวกับเพื่อนชาวญี่ปุ่น เมื่อพักกินควรวางตะเกียบอย่างไร","a":"ปักตะเกียบตั้งในชามข้าว","b":"ถือตะเกียบค้างไว้ตลอด","c":"วางตะเกียบพาดชาม","d":"เสียบตะเกียบลงในอาหาร","correct":2,"explain":"ในญี่ปุ่นและจีน การปักตะเกียบตั้งในชามข้าวเกี่ยวข้องกับพิธีศพ ควรวางตะเกียบพาดชาม"},{"text":"ชาวต่างชาติลูบศีรษะเด็กไทยด้วยความเอ็นดู แต่คนไทยรู้สึกไม่ดี เกิดจากอะไร","a":"ชาวต่างชาติตั้งใจทำร้ายเด็ก","b":"คนไทยไม่ชอบชาวต่างชาติทุกคน","c":"เด็กไทยไม่ชอบให้ใครเอ็นดูเลย","d":"ท่าเดียวกัน แต่ความหมายต่างกัน","correct":3,"explain":"สไลด์ “ท่าเดียวกัน ความหมายต่างกัน” อธิบายว่าคนไทยถือศีรษะเป็นของสูง การลูบศีรษะที่อีกวัฒนธรรมมองว่าเอ็นดู จึงทำให้คนไทยเข้าใจผิดได้"},{"text":"“เหมือนเพื่อเชื่อม ต่างเพื่อเรียนรู้” มีความหมายว่าอย่างไร","a":"ความเหมือนเชื่อมสัมพันธ์ ความต่างช่วยให้เรียนรู้","b":"ความเหมือนทำให้ทะเลาะ ความต่างทำให้แยกกัน","c":"ควรเลือกคบเฉพาะคนที่เหมือนเรา","d":"ควรเปลี่ยนให้ทุกคนเหมือนกันหมด","correct":0,"explain":"สไลด์สรุปว่าความเหมือนช่วยเชื่อมความสัมพันธ์ ความต่างช่วยให้เรียนรู้ และการเคารพความหลากหลายนำไปสู่ความเข้าใจอันดี"},{"text":"ก่อนไปทัศนศึกษาที่ซาอุดีอาระเบีย ข้อใดเป็นการเตรียมตัวที่ดีที่สุด","a":"ทำตามแบบไทยทุกอย่าง ไม่ต้องปรับ","b":"ศึกษาข้อห้ามและมารยาทก่อนเดินทาง","c":"ล้อเลียนการแต่งกายของคนท้องถิ่น","d":"ไม่ยอมลองอาหารท้องถิ่นเลย","correct":1,"explain":"แนวทางเคารพความหลากหลาย คือ ไม่ตัดสิน เรียนรู้ข้อห้ามและมารยาทก่อนเดินทาง ไม่ล้อเลียน และเปิดใจแลกเปลี่ยน"}]},{"id":"exam-soc-12","name":"สังคม ม.2 · เรื่องที่ 12 การผลิตสินค้าและบริการ","subject":"สังคมศึกษา","unit":"หน่วยที่ 9 การจัดสรรทรัพยากร · แผนที่ 12","questions":[{"text":"ข้อใดเป็นปัจจัยการผลิต","a":"ที่ดิน","b":"ภาษี","c":"ฉลากสินค้า","d":"ใบเสร็จ","correct":0,"explain":"ปัจจัยการผลิตมี 4 อย่าง คือ ที่ดิน แรงงาน ทุน และผู้ประกอบการ"},{"text":"ข้อใดเป็นคำถามพื้นฐานของการผลิต","a":"ผลิตที่ไหน เมื่อไร กี่ชิ้น","b":"ใครผลิต ใครขาย ใครซื้อ","c":"ผลิตอะไร อย่างไร เพื่อใคร","d":"ผลิตเท่าไร ขายเท่าไร กำไรเท่าไร","correct":2,"explain":"คำถามพื้นฐานของการผลิต คือ ผลิตอะไร · ผลิตอย่างไร · ผลิตเพื่อใคร"},{"text":"ข้อใดเป็นข้อเสียของการใช้เทคโนโลยีในการผลิต","a":"ผลิตได้มากขึ้น","b":"ผลิตได้เร็วขึ้น","c":"คุณภาพสม่ำเสมอ","d":"ต้องลงทุนสูง","correct":3,"explain":"ข้อเสียของเทคโนโลยี คือ ลงทุนสูง และแรงงานบางส่วนอาจตกงาน ส่วนข้ออื่นเป็นข้อดี"},{"text":"ข้อใดเป็นความหมายของ “การผลิต”","a":"การสร้างหรือเพิ่มประโยชน์ของสินค้าและบริการ","b":"การซื้อสินค้ามาเก็บไว้ใช้เองที่บ้าน","c":"การนำเงินที่เหลือไปฝากไว้ที่ธนาคาร","d":"การทิ้งของที่ไม่ใช้แล้วลงถังขยะ","correct":0,"explain":"การผลิต คือ การสร้างหรือเพิ่มประโยชน์ (อรรถประโยชน์) ของสินค้าและบริการ เพื่อสนองความต้องการของมนุษย์"},{"text":"ข้อใดเป็นปัจจัยการผลิตประเภท “ทุน”","a":"แรงกายของคนงาน","b":"เครื่องจักรในโรงงาน","c":"ที่ดินสำหรับปลูกพืช","d":"การวางแผนของเจ้าของ","correct":1,"explain":"ทุน คือ เครื่องจักร อาคาร เงินทุน ส่วนแรงกายคือแรงงาน ที่ดินคือที่ดิน การวางแผนคือผู้ประกอบการ"},{"text":"ป้าเปิดร้านข้าวซอย ป้าวางแผน ตัดสินใจ และรับความเสี่ยงเอง ป้าจะได้ผลตอบแทนเป็นอะไร","a":"ค่าเช่า","b":"ค่าจ้าง","c":"ดอกเบี้ย","d":"กำไร","correct":3,"explain":"ผู้ประกอบการ คือ ผู้วางแผน ตัดสินใจ และรับความเสี่ยง ได้ผลตอบแทนเป็นกำไร (ที่ดิน → ค่าเช่า · แรงงาน → ค่าจ้าง · ทุน → ดอกเบี้ย)"},{"text":"ชาวสวนใช้โดรนพ่นปุ๋ย เป็นการใช้สิ่งใดในการผลิต","a":"การออมทรัพย์","b":"สิทธิผู้บริโภค","c":"เทคโนโลยีการผลิต","d":"เศรษฐกิจพอเพียง","correct":2,"explain":"เทคโนโลยีการผลิต คือ การนำความรู้และเครื่องมือมาช่วยผลิต สไลด์ยกตัวอย่างโดรนพ่นปุ๋ย ระบบรดน้ำอัตโนมัติ หุ่นยนต์ในโรงงาน"},{"text":"โรงงานซื้อหุ่นยนต์มาทำงานแทนคน จะเกิดผลอย่างไร","a":"ผลิตได้ช้าลง และคนงานได้เงินเพิ่ม","b":"ผลิตได้เร็วขึ้น แต่คนงานบางส่วนอาจตกงาน","c":"ไม่ต้องลงทุนเลย และคนงานเพิ่มขึ้น","d":"คุณภาพแย่ลง และขายไม่ได้เลย","correct":1,"explain":"เทคโนโลยีมีข้อดีคือผลิตได้มาก เร็ว คุณภาพสม่ำเสมอ แต่มีข้อเสียคือลงทุนสูงและแรงงานบางส่วนอาจตกงาน"},{"text":"ข้อใดสรุปการผลิตอย่างมีประสิทธิภาพได้ครบที่สุด","a":"ได้มาก คุณภาพต่ำ ต้นทุนสูง","b":"ได้น้อย คุณภาพดี ต้นทุนสูง","c":"ได้มาก ต้นทุนต่ำ ทำลายสิ่งแวดล้อม","d":"ได้มาก คุณภาพดี ต้นทุนต่ำ ไม่ทิ้งเศษ","correct":3,"explain":"สไลด์สรุปข้อคิดว่า ผลิตอย่างมีประสิทธิภาพ = ได้มาก คุณภาพดี ต้นทุนต่ำ ไม่ทิ้งเศษ ใช้ทรัพยากรคุ้มค่า และไม่ทำลายสิ่งแวดล้อม"},{"text":"ร้านทำร่ม 4 ร้าน ร้านใดผลิตอย่างมีประสิทธิภาพที่สุด","a":"ร้าน ก ทำร่มได้มาก แต่ทิ้งน้ำเสียลงคลอง","b":"ร้าน ข ทำร่มคุณภาพดี ต้นทุนต่ำ ใช้วัสดุคุ้มค่า","c":"ร้าน ค ทำร่มได้น้อย และต้นทุนสูงมาก","d":"ร้าน ง ทำร่มได้เร็ว แต่ร่มพังง่าย","correct":1,"explain":"เมื่อประเมินตามหลักการผลิตอย่างมีประสิทธิภาพ (ได้มาก คุณภาพดี ต้นทุนต่ำ ใช้ทรัพยากรคุ้มค่า ไม่ทำลายสิ่งแวดล้อม) ร้าน ข ทำได้ครบที่สุด ร้านอื่นขาดบางข้อ"}]},{"id":"exam-soc-13","name":"สังคม ม.2 · เรื่องที่ 13 การผลิตในท้องถิ่น","subject":"สังคมศึกษา","unit":"หน่วยที่ 9 การจัดสรรทรัพยากร · แผนที่ 13","questions":[{"text":"การผลิตในท้องถิ่นมักเป็นการผลิตขนาดใด","a":"ขนาดใหญ่มาก","b":"ขนาดเล็กถึงกลาง","c":"ขนาดใหญ่ระดับโลก","d":"ไม่มีขนาดแน่นอน","correct":1,"explain":"การผลิตในท้องถิ่นมักเป็นขนาดเล็กถึงกลาง เช่น ครัวเรือน วิสาหกิจชุมชน สหกรณ์"},{"text":"ข้อใดเป็นสินค้าหัตถกรรมของเชียงใหม่","a":"ลำไยอบแห้ง","b":"ไส้อั่ว","c":"ร่มบ่อสร้าง","d":"โฮมสเตย์","correct":2,"explain":"หัตถกรรมของเชียงใหม่ ได้แก่ ร่มบ่อสร้าง เครื่องเงินวัวลาย แกะสลักไม้บ้านถวาย ผ้าซิ่นตีนจกแม่แจ่ม ส่วนลำไยเป็นเกษตร ไส้อั่วเป็นอาหารแปรรูป โฮมสเตย์เป็นบริการ"},{"text":"การเผาเศษวัสดุการเกษตร ทำให้เกิดปัญหาใด","a":"น้ำท่วม","b":"ดินถล่ม","c":"ภัยแล้ง","d":"หมอกควัน","correct":3,"explain":"การเผาเศษวัสดุการเกษตรทำให้เกิดหมอกควัน เป็นปัญหาด้านสิ่งแวดล้อม"},{"text":"การผลิตในท้องถิ่นใช้สิ่งใดเป็นหลัก","a":"ทรัพยากร แรงงาน และภูมิปัญญาในพื้นที่","b":"วัตถุดิบนำเข้าจากต่างประเทศทั้งหมด","c":"เครื่องจักรขนาดใหญ่จากโรงงาน","d":"แรงงานต่างชาติเป็นส่วนใหญ่","correct":0,"explain":"การผลิตในท้องถิ่น คือ ผลิตสินค้าและบริการโดยใช้ทรัพยากร แรงงาน และภูมิปัญญาในพื้นที่"},{"text":"ไส้อั่ว แคบหมู น้ำพริกหนุ่ม จัดเป็นของดีเชียงใหม่ประเภทใด","a":"เกษตร","b":"หัตถกรรม","c":"อาหารแปรรูป","d":"บริการ","correct":2,"explain":"สไลด์จัดไส้อั่ว แคบหมู น้ำพริกหนุ่ม ไว้ในกลุ่มของดีเชียงใหม่ประเภทอาหารแปรรูป"},{"text":"ชาวบ้านแม่กำปองปลูกกาแฟขาย และเปิดโฮมสเตย์ เป็นการผลิตประเภทใดบ้าง","a":"หัตถกรรม และ อาหารแปรรูป","b":"เกษตร และ บริการ","c":"อุตสาหกรรม และ เหมืองแร่","d":"ประมง และ ป่าไม้","correct":1,"explain":"สไลด์จัดกาแฟบ้านแม่กำปองเป็นของดีด้านเกษตร และโฮมสเตย์เป็นของดีด้านบริการ"},{"text":"ถ้าต้องการซื้อเครื่องเงินฝีมือชาวเชียงใหม่ ควรไปที่ใด","a":"บ้านแม่กำปอง","b":"ถนนวัวลาย","c":"อ.แม่แจ่ม","d":"บ้านถวาย","correct":1,"explain":"เครื่องเงินเป็นของดีของถนนวัวลาย ส่วนแม่กำปอง = กาแฟ แม่แจ่ม = ผ้าซิ่นตีนจก บ้านถวาย = แกะสลักไม้"},{"text":"ผ้าซิ่นตีนจกอาจหายไปในอนาคต ถ้าเกิดปัญหาใด","a":"มีนักท่องเที่ยวมาซื้อมากขึ้น","b":"คนในชุมชนช่วยกันซื้อมากขึ้น","c":"มีโรงเรียนสอนทอผ้าเพิ่มขึ้น","d":"คนรุ่นใหม่ไม่สืบทอดภูมิปัญญา","correct":3,"explain":"ปัญหาด้านสังคมของการผลิตในท้องถิ่น คือ คนรุ่นใหม่ไม่สืบทอดภูมิปัญญา ถ้าเกิดขึ้น สินค้าที่ต้องใช้ภูมิปัญญาจะหายไป ส่วนข้ออื่นช่วยให้ของดีท้องถิ่นอยู่ต่อ"},{"text":"“ราคาผลผลิตไม่แน่นอน แรงงานย้ายเข้าเมือง น้ำเสียจากการแปรรูป” แสดงว่าปัญหาการผลิตในท้องถิ่นเป็นอย่างไร","a":"มีหลายด้าน ทั้งเศรษฐกิจ สังคม สิ่งแวดล้อม","b":"มีเฉพาะปัญหาด้านเศรษฐกิจอย่างเดียว","c":"มีเฉพาะปัญหาด้านสิ่งแวดล้อมอย่างเดียว","d":"ไม่มีปัญหาใดที่ต้องแก้ไขเลย","correct":0,"explain":"ทั้งสามตัวอย่างอยู่คนละด้าน คือ ราคาไม่แน่นอน = เศรษฐกิจ แรงงานย้ายเข้าเมือง = สังคม น้ำเสีย = สิ่งแวดล้อม เมื่อรวมกันจึงสรุปได้ว่าปัญหามีหลายด้าน"},{"text":"ข้อใดช่วยให้ของดีท้องถิ่นอยู่ได้ดีที่สุด","a":"ซื้อสินค้าจากโรงงานแทนของท้องถิ่น","b":"ให้คนรุ่นใหม่ย้ายไปทำงานในเมือง","c":"คนในท้องถิ่นช่วยกันผลิต ซื้อ และสืบทอด","d":"เผาเศษวัสดุเกษตรเพื่อประหยัดเวลา","correct":2,"explain":"สไลด์สรุปข้อคิดว่า ของดีท้องถิ่นอยู่ได้เพราะคนในท้องถิ่นช่วยกันผลิต ซื้อ และสืบทอด ส่วนข้ออื่นเป็นสาเหตุของปัญหา"}]},{"id":"exam-soc-14","name":"สังคม ม.2 · เรื่องที่ 14 สิทธิผู้บริโภค","subject":"สังคมศึกษา","unit":"หน่วยที่ 9 การจัดสรรทรัพยากร · แผนที่ 14","questions":[{"text":"ซื้อปลั๊กพ่วง ควรดูเครื่องหมายใด","a":"เลข อย.","b":"เครื่องหมาย มอก.","c":"ใบเสร็จรับเงิน","d":"รีวิวออนไลน์","correct":1,"explain":"เครื่องหมาย มอก. ใช้กับผลิตภัณฑ์อุตสาหกรรม เช่น ปลั๊กพ่วง หมวกกันน็อก ส่วนเลข อย. ใช้กับอาหาร"},{"text":"อาหารไม่ปลอดภัย ควรร้องเรียนหน่วยงานใด","a":"สคบ.","b":"สมอ.","c":"อย.","d":"เทศบาล","correct":2,"explain":"อย. (สำนักงานคณะกรรมการอาหารและยา) สายด่วน 1556 ดูแลเรื่องอาหาร ยา เครื่องสำอาง"},{"text":"ข้อใดเป็นสิทธิผู้บริโภค","a":"สิทธิได้สินค้าฟรีทุกครั้ง","b":"สิทธิไม่ต้องจ่ายภาษี","c":"สิทธิคืนสินค้าได้ตลอดไป","d":"สิทธิได้รับความปลอดภัยจากสินค้า","correct":3,"explain":"สิทธิผู้บริโภค 5 ประการ คือ ได้รับข่าวสาร อิสระในการเลือก ความปลอดภัย ความเป็นธรรมในการทำสัญญา และได้รับการชดเชย"},{"text":"ทำไมควรขอใบเสร็จทุกครั้งที่ซื้อของ","a":"ใช้เป็นหลักฐานเมื่อต้องร้องเรียน","b":"ใช้แทนเงินซื้อของครั้งหน้า","c":"ใช้ลดราคาสินค้าได้ทันที","d":"ใช้แลกของรางวัลจากร้าน","correct":0,"explain":"วิธีร้องเรียนขั้นที่ 2 คือ เก็บหลักฐาน เช่น ใบเสร็จ ฉลาก ภาพถ่าย ใบเสร็จจึงใช้เป็นหลักฐานเมื่อต้องร้องเรียน"},{"text":"ข้อมูลใดบนฉลาก บอกได้ว่าอาหารยังกินได้อยู่หรือไม่","a":"ชื่อของสินค้านั้น","b":"วันผลิตและวันหมดอายุ","c":"ราคาของสินค้านั้น","d":"ชื่อและที่อยู่ผู้ผลิต","correct":1,"explain":"ฉลากที่ดีต้องมีวันผลิตและวันหมดอายุ ซึ่งบอกว่าสินค้ายังใช้หรือกินได้หรือไม่"},{"text":"ซื้อขนมแล้วเปิดพบว่าหมดอายุ ขั้นแรกควรทำอย่างไร","a":"โพสต์ต่อว่าร้านในโซเชียลทันที","b":"ทิ้งขนมแล้วลืมไป","c":"ติดต่อร้านค้าหรือผู้ขายก่อน","d":"แจ้งตำรวจทันที","correct":2,"explain":"วิธีร้องเรียน 4 ขั้น เริ่มจาก ติดต่อร้านค้าหรือผู้ขายก่อน → เก็บหลักฐาน → ร้องเรียนหน่วยงาน → ติดตามผล"},{"text":"ซื้อของออนไลน์ ควรทำอย่างไรตามหลักการเลือกซื้อ","a":"ซื้อร้านที่ถูกที่สุดโดยไม่ดูอะไร","b":"ซื้อตามที่เพื่อนบอกทันที","c":"โอนเงินก่อนแล้วค่อยถามรายละเอียด","d":"ดูรีวิวและช่องทางติดต่อของร้าน","correct":3,"explain":"หลักการเลือกซื้อข้อ 4 คือ เลือกร้านน่าเชื่อถือ ถ้าซื้อออนไลน์ให้ดูรีวิวและช่องทางติดต่อ"},{"text":"ฉลากขนมเขียนว่า “ไม่มีน้ำตาล” แต่ความจริงมีน้ำตาล ผู้บริโภคถูกละเมิดสิทธิใดชัดเจนที่สุด","a":"สิทธิอิสระในการเลือก","b":"สิทธิได้รับข่าวสารที่ถูกต้อง","c":"สิทธิความเป็นธรรมในสัญญา","d":"สิทธิได้รับการชดเชย","correct":1,"explain":"สิทธิได้รับข่าวสาร คือ ได้รับคำพรรณนาคุณภาพที่ถูกต้องและเพียงพอ ฉลากที่ให้ข้อมูลไม่ตรงความจริงจึงละเมิดสิทธินี้โดยตรง"},{"text":"ข้อใดเรียงขั้นตอนการร้องเรียนได้ถูกต้อง","a":"ร้องเรียนหน่วยงาน → ติดต่อร้าน → ติดตามผล → เก็บหลักฐาน","b":"เก็บหลักฐาน → ติดตามผล → ติดต่อร้าน → ร้องเรียนหน่วยงาน","c":"ติดต่อร้าน → เก็บหลักฐาน → ร้องเรียนหน่วยงาน → ติดตามผล","d":"ติดตามผล → ร้องเรียนหน่วยงาน → เก็บหลักฐาน → ติดต่อร้าน","correct":2,"explain":"เมื่อนำทั้ง 4 ขั้นมาเรียงกัน จะเป็น ติดต่อร้านค้าก่อน → เก็บหลักฐาน → ร้องเรียนหน่วยงาน → ติดตามผล"},{"text":"เพื่อน 4 คนซื้อของ ใครเป็นผู้บริโภคที่รู้เท่าทันที่สุด","a":"ต้น เปรียบเทียบราคา ตรวจฉลาก และขอใบเสร็จ","b":"ฝน ซื้อเพราะลดราคา แม้ไม่จำเป็น","c":"มด ซื้อจากร้านที่ไม่มีช่องทางติดต่อ","d":"บี ซื้อปลั๊กพ่วงไม่มี มอก. เพราะถูก","correct":0,"explain":"หลักการเลือกซื้อ คือ ซื้อตามความจำเป็น เปรียบเทียบคุณภาพและราคา ตรวจฉลากและเครื่องหมายรับรอง เลือกร้านน่าเชื่อถือ และขอใบเสร็จ ต้นทำได้ครบ ส่วนคนอื่นขัดกับหลักการ"}]},{"id":"exam-soc-15","name":"สังคม ม.2 · เรื่องที่ 15 หลักปรัชญาของเศรษฐกิจพอเพียง","subject":"สังคมศึกษา","unit":"หน่วยที่ 10 เศรษฐกิจพอเพียง · แผนที่ 15","questions":[{"text":"ข้อใดคือ “3 ห่วง” ของเศรษฐกิจพอเพียง","a":"รอบรู้ รอบคอบ ระมัดระวัง","b":"พอประมาณ มีเหตุผล มีภูมิคุ้มกัน","c":"ซื่อสัตย์ ขยัน อดทน","d":"เศรษฐกิจ สังคม สิ่งแวดล้อม","correct":1,"explain":"3 ห่วง คือ ความพอประมาณ ความมีเหตุผล และมีภูมิคุ้มกันที่ดีในตัว"},{"text":"ข้อใดคือ “2 เงื่อนไข” ที่เป็นฐานของเศรษฐกิจพอเพียง","a":"เงินทุน และ ที่ดิน","b":"ตลาด และ ราคา","c":"รายได้ และ รายจ่าย","d":"ความรู้ และ คุณธรรม","correct":3,"explain":"2 เงื่อนไข คือ เงื่อนไขความรู้ (รอบรู้ รอบคอบ ระมัดระวัง) และเงื่อนไขคุณธรรม (ซื่อสัตย์ ขยัน อดทน แบ่งปัน)"},{"text":"หลักปรัชญาของเศรษฐกิจพอเพียง ใครเป็นผู้พระราชทาน","a":"รัชกาลที่ 5","b":"รัชกาลที่ 7","c":"รัชกาลที่ 9","d":"รัชกาลที่ 10","correct":2,"explain":"เศรษฐกิจพอเพียงเป็นแนวทางการดำเนินชีวิตที่รัชกาลที่ 9 พระราชทาน"},{"text":"“ความพอประมาณ” หมายถึงข้อใด","a":"พอดี ไม่มากหรือน้อยเกินไป","b":"ใช้จ่ายให้มากที่สุด","c":"ประหยัดจนไม่กินอะไรเลย","d":"ทำตามที่คนอื่นบอก","correct":0,"explain":"ความพอประมาณ คือ พอดี ไม่มากไม่น้อยเกินไป และไม่เบียดเบียนตนเองและผู้อื่น"},{"text":"เศรษฐกิจพอเพียงนำไปใช้ได้กับระดับใด","a":"เฉพาะเกษตรกรในชนบทเท่านั้น","b":"ทุกระดับ ตั้งแต่บุคคลถึงประเทศ","c":"เฉพาะคนที่มีฐานะร่ำรวย","d":"เฉพาะหน่วยงานของรัฐบาล","correct":1,"explain":"เศรษฐกิจพอเพียงใช้ได้ทุกระดับ คือ บุคคล → ครอบครัว → ชุมชน → ประเทศ"},{"text":"“ใช้จ่ายพอดี มีเงินออม ไม่เป็นหนี้เกินตัว” เป็นความสมดุลด้านใด","a":"ด้านเศรษฐกิจ","b":"ด้านสังคม","c":"ด้านสิ่งแวดล้อม","d":"ด้านวัฒนธรรม","correct":0,"explain":"ด้านเศรษฐกิจ คือ ใช้จ่ายพอดี มีเงินออม ไม่เป็นหนี้เกินตัว"},{"text":"ก่อนซื้อโทรศัพท์ใหม่ นักเรียนคิดว่า “ซื้อแล้วจะเกิดผลอะไรตามมา” เป็นการใช้หลักใด","a":"ความพอประมาณ","b":"เงื่อนไขคุณธรรม","c":"ความมีเหตุผล","d":"มีภูมิคุ้มกันที่ดี","correct":2,"explain":"ความมีเหตุผล คือ คิดถึงเหตุปัจจัยและผลที่จะตามมาก่อนตัดสินใจ"},{"text":"ครอบครัวหนึ่งเก็บเงินสำรองไว้เผื่อตกงาน การกระทำนี้ดีอย่างไร","a":"ทำให้ไม่ต้องทำงานอีกเลย","b":"ทำให้ใช้เงินฟุ่มเฟือยได้มากขึ้น","c":"ทำให้ไม่ต้องช่วยเหลือผู้อื่น","d":"พร้อมรับการเปลี่ยนแปลงและความเสี่ยง","correct":3,"explain":"การเก็บเงินสำรองตรงกับห่วง “มีภูมิคุ้มกันที่ดีในตัว” คือ พร้อมรับการเปลี่ยนแปลงและความเสี่ยงที่อาจเกิดขึ้น"},{"text":"เมื่อใช้ 3 ห่วง 2 เงื่อนไข จะพาชีวิตไปสู่สิ่งใด","a":"ชีวิตสมดุล มั่นคง และยั่งยืน","b":"ชีวิตร่ำรวยได้เร็วที่สุด","c":"ชีวิตที่ไม่ต้องทำงานเลย","d":"ชีวิตที่มีหนี้มากขึ้น","correct":0,"explain":"สไลด์สรุปว่า 3 ห่วง 2 เงื่อนไข พาชีวิตสมดุล 4 มิติ (เศรษฐกิจ สังคม สิ่งแวดล้อม วัฒนธรรม) อย่างมั่นคงยั่งยืน"},{"text":"ข้อใดเป็นการใช้เงื่อนไขคุณธรรมได้ดีที่สุด","a":"ขายผักแพงกว่าคนอื่นเพื่อเอากำไร","b":"ขายผักแล้วโกหกว่าไม่ใช้สารเคมี","c":"ขายผักด้วยความซื่อสัตย์ต่อลูกค้า","d":"ไม่ยอมแบ่งปันผักให้เพื่อนบ้าน","correct":2,"explain":"เงื่อนไขคุณธรรม คือ ซื่อสัตย์ ขยัน อดทน แบ่งปัน การขายอย่างซื่อสัตย์จึงตรงที่สุด ส่วนข้ออื่นขาดความซื่อสัตย์หรือการแบ่งปัน"}]},{"id":"exam-soc-16","name":"สังคม ม.2 · เรื่องที่ 16 ปัญหาและแนวทางการผลิตในท้องถิ่น","subject":"สังคมศึกษา","unit":"หน่วยที่ 10 เศรษฐกิจพอเพียง · แผนที่ 16","questions":[{"text":"OTOP ย่อมาจากโครงการใด","a":"หนึ่งอำเภอ หนึ่งโรงงาน","b":"หนึ่งตำบล หนึ่งผลิตภัณฑ์","c":"หนึ่งจังหวัด หนึ่งตลาด","d":"หนึ่งหมู่บ้าน หนึ่งร้านค้า","correct":1,"explain":"OTOP คือ โครงการหนึ่งตำบล หนึ่งผลิตภัณฑ์"},{"text":"“ผลผลิตออกพร้อมกัน ล้นตลาด ราคาตก” เป็นปัญหาด้านใด","a":"ด้านทุน","b":"ด้านตลาด","c":"ด้านราคา","d":"ด้านแรงงาน","correct":2,"explain":"สไลด์จัดปัญหาผลผลิตออกพร้อมกัน ล้นตลาด ราคาตก ถูกกดราคา ไว้ในปัญหาด้านราคา"},{"text":"ชุมชนลดต้นทุนการผลิตได้ด้วยสิ่งใด","a":"กู้เงินนอกระบบ","b":"ซื้อสารเคมีเพิ่ม","c":"จ้างพ่อค้าคนกลาง","d":"ใช้ปุ๋ยอินทรีย์","correct":3,"explain":"แนวทางแก้ปัญหาด้านทุนข้อหนึ่ง คือ ลดต้นทุนด้วยปุ๋ยอินทรีย์"},{"text":"ทำไมการกู้เงินนอกระบบจึงเป็นปัญหาของผู้ผลิตในท้องถิ่น","a":"เพราะดอกเบี้ยสูง","b":"เพราะไม่มีดอกเบี้ย","c":"เพราะรัฐช่วยจ่ายให้","d":"เพราะได้เงินมาฟรี","correct":0,"explain":"ปัญหาด้านทุนคือ ขาดเงินทุนหมุนเวียน ไม่มีหลักทรัพย์ค้ำประกัน จึงต้องกู้นอกระบบซึ่งดอกเบี้ยสูง"},{"text":"ทำไมผู้ซื้อจำนวนมากจึงไม่รู้จักสินค้าท้องถิ่น","a":"สินค้ามีคุณภาพดีเกินไป","b":"ขายในตลาดชุมชนมากเกินไป","c":"ไม่มีตราสินค้าและมาตรฐาน","d":"มีบรรจุภัณฑ์สวยเกินไป","correct":2,"explain":"ปัญหาด้านตลาด คือ ขายผ่านพ่อค้าคนกลาง ช่องทางจำหน่ายน้อย ไม่มีตราสินค้าและมาตรฐาน ผู้ซื้อจึงไม่รู้จักสินค้า"},{"text":"ลำไยล้นตลาด ราคาตก ชาวสวนควรแก้อย่างไร","a":"เททิ้งให้หมด","b":"แปรรูปเป็นลำไยอบแห้ง","c":"ขายให้คนกลางราคาต่ำ","d":"เลิกปลูกทันที","correct":1,"explain":"แนวทางแก้ปัญหาด้านราคา คือ แปรรูปเพิ่มมูลค่า เช่น ลำไยอบแห้ง น้ำลำไย และสร้างตราสินค้า"},{"text":"กลุ่มแม่บ้านทำน้ำพริกแต่ขาดเงินทุน ควรทำอย่างไร","a":"กู้เงินนอกระบบดอกเบี้ยสูง","b":"ขายบ้านมาลงทุน","c":"เลิกทำน้ำพริก","d":"รวมกลุ่มเป็นวิสาหกิจชุมชน","correct":3,"explain":"แนวทางแก้ปัญหาด้านทุน คือ รวมกลุ่มเป็นสหกรณ์หรือวิสาหกิจชุมชน ออมในกลุ่มออมทรัพย์ กู้จากกองทุนหมู่บ้านหรือในระบบ"},{"text":"ชาวบ้านขายของได้น้อยเพราะช่องทางจำหน่ายน้อย วิธีใดตรงกับปัญหามากที่สุด","a":"ขายออนไลน์และไลฟ์สด","b":"ใช้ปุ๋ยอินทรีย์","c":"กู้จากกองทุนหมู่บ้าน","d":"ออมในกลุ่มออมทรัพย์","correct":0,"explain":"ช่องทางจำหน่ายน้อยเป็นปัญหาด้านตลาด จึงต้องแก้ด้วยการหาช่องทาง เช่น ขายออนไลน์และไลฟ์สด ส่วนตัวเลือกอื่นเป็นวิธีแก้ปัญหาด้านทุน"},{"text":"ข้อใดจับคู่ปัญหากับวิธีแก้ได้ถูกต้องครบทั้ง 3 ด้าน","a":"ทุน–แปรรูป · ตลาด–รวมกลุ่ม · ราคา–หาช่องทาง","b":"ทุน–หาช่องทาง · ตลาด–แปรรูป · ราคา–รวมกลุ่ม","c":"ทุน–รวมกลุ่ม · ตลาด–หาช่องทาง · ราคา–แปรรูป","d":"ทุน–ลดราคา · ตลาด–เลิกขาย · ราคา–กู้นอกระบบ","correct":2,"explain":"สไลด์สรุปข้อคิดว่า รวมกลุ่มแก้ทุน หาช่องทางแก้ตลาด แปรรูปแก้ราคา"},{"text":"ชุมชนปลูกลำไยอย่างเดียว ราคาตกทุกปี แนวทางใดดีที่สุดในระยะยาว","a":"ปลูกลำไยเพิ่มเป็นสองเท่า","b":"ปลูกพืชหลายชนิด","c":"กู้นอกระบบมาลงทุนเพิ่ม","d":"ขายให้คนกลางตามราคาที่กด","correct":1,"explain":"แนวทางแก้ปัญหาด้านราคาข้อหนึ่ง คือ ปลูกพืชหลายชนิด จึงไม่ต้องพึ่งราคาพืชชนิดเดียว ซึ่งตรงกับหลักสร้างภูมิคุ้มกันให้ชุมชน"}]},{"id":"exam-soc-17","name":"สังคม ม.2 · เรื่องที่ 17 เศรษฐกิจพอเพียงกับการผลิต","subject":"สังคมศึกษา","unit":"หน่วยที่ 10 เศรษฐกิจพอเพียง · แผนที่ 17","questions":[{"text":"SMEs หมายถึงอะไร","a":"บริษัทข้ามชาติขนาดใหญ่","b":"หน่วยงานรัฐที่เก็บภาษี","c":"วิสาหกิจขนาดกลางและขนาดย่อม","d":"ธนาคารของรัฐบาล","correct":2,"explain":"SMEs (Small and Medium Enterprises) = วิสาหกิจขนาดกลางและขนาดย่อม เช่น ร้านน้ำพริก ร้านกาแฟ"},{"text":"เกษตรทฤษฎีใหม่ พื้นที่ร้อยละ 10 ใช้ทำอะไร","a":"สระน้ำเก็บน้ำ","b":"นาปลูกข้าว","c":"ไม้ผล พืชไร่ พืชผัก","d":"ที่อยู่อาศัย เลี้ยงสัตว์","correct":3,"explain":"เกษตรทฤษฎีใหม่แบ่งที่ 30 : 30 : 30 : 10 คือ สระน้ำ นาข้าว ไม้ผลพืชผัก และร้อยละ 10 เป็นที่อยู่อาศัย เลี้ยงสัตว์ และอื่นๆ"},{"text":"เกษตรทฤษฎีใหม่ขั้นที่ 1 คืออะไร","a":"ร่วมมือกับบริษัทขนาดใหญ่","b":"ผลิตให้พอกินพอใช้ในครอบครัว","c":"ส่งผลผลิตออกไปต่างประเทศ","d":"รวมกลุ่มกันเป็นสหกรณ์","correct":1,"explain":"เกษตรทฤษฎีใหม่ 3 ขั้น คือ 1) ผลิตให้พอกินพอใช้ในครอบครัว 2) รวมพลังเป็นกลุ่มหรือสหกรณ์ 3) ร่วมมือกับแหล่งเงินทุนหรือภาคธุรกิจ"},{"text":"กำไรคำนวณได้อย่างไร","a":"รายรับ − ต้นทุน","b":"ต้นทุน − รายรับ","c":"รายรับ + ต้นทุน","d":"ราคาขาย × ต้นทุน","correct":0,"explain":"สไลด์บัญชีต้นทุน–กำไรระบุว่า กำไร = รายรับ − ต้นทุน"},{"text":"ถ้าคำนวณแล้วกำไรติดลบ หมายความว่าอย่างไร","a":"ได้กำไรมาก","b":"ขายได้หมด","c":"ขาดทุน","d":"เท่าทุนพอดี","correct":2,"explain":"สไลด์ระบุว่า กำไร = รายรับ − ต้นทุน ถ้าติดลบ = ขาดทุน"},{"text":"ขายสินค้าได้ 1,000 บาท ต้นทุน 700 บาท ได้กำไรเท่าไร","a":"700 บาท","b":"300 บาท","c":"1,700 บาท","d":"1,000 บาท","correct":1,"explain":"กำไร = รายรับ − ต้นทุน = 1,000 − 700 = 300 บาท"},{"text":"ชาวนามีที่ดิน 10 ไร่ ทำตามเกษตรทฤษฎีใหม่ ควรขุดสระน้ำกี่ไร่","a":"1 ไร่","b":"5 ไร่","c":"3 ไร่","d":"10 ไร่","correct":2,"explain":"เกษตรทฤษฎีใหม่ให้ใช้ร้อยละ 30 เป็นสระน้ำ ที่ 10 ไร่ × 30% = 3 ไร่"},{"text":"ร้านกาแฟกู้เงินมาขยายร้านใหญ่เกินกว่าจำนวนลูกค้าจริง ขัดกับหลัก SMEs พอเพียงข้อใด","a":"ไม่กู้เงินลงทุนเกินตัว","b":"ทำบัญชีรายรับรายจ่าย","c":"ใช้วัตถุดิบในท้องถิ่น","d":"ซื่อสัตย์ต่อลูกค้า","correct":0,"explain":"หลัก SMEs พอเพียงข้อหนึ่งคือ ไม่กู้เงินลงทุนเกินตัว และผลิตตามกำลังและความต้องการจริง การกู้มาขยายเกินลูกค้าจริงจึงขัดหลักนี้"},{"text":"ร้านน้ำพริกทำบัญชี ใช้พริกจากชาวบ้าน ไม่ปลอมปน และผลิตตามความต้องการจริง สรุปได้ว่าอย่างไร","a":"เป็นธุรกิจที่จะขาดทุนแน่นอน","b":"เป็นธุรกิจที่เอาเปรียบลูกค้า","c":"เป็นธุรกิจที่ผิดกฎหมาย","d":"เป็น SMEs พอเพียงที่อยู่ได้ยั่งยืน","correct":3,"explain":"เมื่อรวมพฤติกรรมทั้งหมดจะตรงกับหลัก SMEs พอเพียง สไลด์สรุปว่าผลิตพอดีตัว รู้ต้นทุน ทำอย่างสุจริต ผู้ผลิตในท้องถิ่นก็อยู่ได้อย่างยั่งยืน"},{"text":"ร้านแปรรูปอาหาร 4 ร้าน ร้านใดทำตามหลักเศรษฐกิจพอเพียงได้ดีที่สุด","a":"ร้าน ก ไม่ทำบัญชี ไม่รู้ว่ากำไรเท่าไร","b":"ร้าน ข ทำบัญชี รู้ต้นทุน ขายอย่างซื่อสัตย์","c":"ร้าน ค ปลอมปนวัตถุดิบเพื่อลดต้นทุน","d":"ร้าน ง กู้เงินลงทุนเกินตัวเพื่อขยายร้าน","correct":1,"explain":"ร้าน ข ทำตามหลัก SMEs พอเพียงครบ คือ ทำบัญชี รู้ต้นทุน และซื่อสัตย์ต่อลูกค้า ส่วนร้านอื่นขัดหลักข้อใดข้อหนึ่ง"}]},{"id":"exam-soc-18","name":"สังคม ม.2 · เรื่องที่ 18 การออมและการลงทุน","subject":"สังคมศึกษา","unit":"หน่วยที่ 11 การออมและการลงทุน · แผนที่ 18","questions":[{"text":"การออมคำนวณได้อย่างไร","a":"รายได้ + รายจ่ายเพื่อการบริโภค","b":"รายได้ − รายจ่ายเพื่อการบริโภค","c":"รายจ่ายเพื่อการบริโภค − รายได้","d":"รายได้ × อัตราดอกเบี้ยเงินฝาก","correct":1,"explain":"ออม = รายได้ − รายจ่ายเพื่อการบริโภค"},{"text":"สลากออมทรัพย์ เช่น สลากออมสิน มีจุดเด่นอย่างไร","a":"เสียเงินต้นหมดถ้าไม่ถูกรางวัล","b":"ได้ความคุ้มครองชีวิตด้วย","c":"ได้เงินต้นคืน และมีโอกาสถูกรางวัล","d":"ได้เงินปันผลจากสหกรณ์","correct":2,"explain":"สลากออมทรัพย์ได้เงินต้นคืนเมื่อครบกำหนด และมีโอกาสถูกรางวัล ส่วนความคุ้มครองเป็นของประกันชีวิต เงินปันผลเป็นของสหกรณ์"},{"text":"การลงทุน คือการนำเงินไปซื้อสิ่งใด","a":"สินค้าทุน เพื่อให้เกิดรายได้ในอนาคต","b":"ขนมและเครื่องดื่มเพื่อกินเล่น","c":"ของตามกระแสเพื่ออวดเพื่อน","d":"ของขวัญเพื่อมอบให้คนอื่น","correct":0,"explain":"การลงทุน คือ นำเงินไปซื้อสินค้าทุน (เครื่องจักร อาคาร สินทรัพย์) เพื่อให้เกิดผลตอบแทนหรือรายได้ในอนาคต"},{"text":"ข้อใดอธิบายเงินฝากออมทรัพย์ได้ถูกต้อง","a":"ถอนได้ทันที ดอกเบี้ยสูงมาก","b":"ต้องฝากครบกำหนดจึงถอนได้","c":"ไม่ได้รับดอกเบี้ยเลย","d":"ถอนได้ทันที ดอกเบี้ยต่ำ","correct":3,"explain":"ออมทรัพย์ถอนได้ทันที ดอกเบี้ยต่ำ ส่วนฝากประจำต้องฝากตามระยะเวลา ดอกเบี้ยสูงกว่า"},{"text":"การออมมีความสำคัญต่อตนเองและครอบครัวอย่างไร","a":"ทำให้ใช้จ่ายตามใจได้มากขึ้น","b":"มีเงินสำรองไว้ใช้ยามจำเป็น","c":"ทำให้ไม่ต้องทำงานอีก","d":"ทำให้ไม่ต้องจ่ายภาษี","correct":1,"explain":"ความสำคัญของการออมต่อตนเองและครอบครัว คือ มีเงินสำรองยามจำเป็น"},{"text":"ถ้าธนาคารเพิ่มอัตราดอกเบี้ยเงินฝากให้สูงขึ้น คนจะออมอย่างไร","a":"ออมน้อยลง","b":"เลิกออม","c":"ออมมากขึ้น","d":"ไม่เปลี่ยนแปลงเลย","correct":2,"explain":"ปัจจัยที่กำหนดการออม: อัตราดอกเบี้ยเงินฝากสูง → ออมมาก"},{"text":"ครูอยากออมเงินและได้ความคุ้มครองชีวิตไปพร้อมกัน ควรเลือกการออมแบบใด","a":"พันธบัตรรัฐบาล","b":"สลากออมทรัพย์","c":"ประกันชีวิต","d":"เงินฝากประจำ","correct":2,"explain":"ประกันชีวิต คือ ออมพร้อมความคุ้มครอง (ต้องส่งเบี้ยต่อเนื่อง)"},{"text":"ช่วงดอกเบี้ยเงินกู้สูง เจ้าของโรงงานยังไม่ซื้อเครื่องจักรใหม่ เพราะเหตุใด","a":"เพราะเครื่องจักรไม่มีขายในประเทศ","b":"เพราะดอกเบี้ยเงินกู้สูง จึงลงทุนน้อยลง","c":"เพราะรัฐบาลห้ามซื้อเครื่องจักร","d":"เพราะดอกเบี้ยสูงทำให้ได้กำไรมากขึ้น","correct":1,"explain":"ปัจจัยที่กำหนดการลงทุน: อัตราดอกเบี้ยเงินกู้สูง → ลงทุนน้อย การซื้อเครื่องจักรคือการลงทุน เจ้าของโรงงานจึงชะลอไว้"},{"text":"ข้อใดสรุปความสัมพันธ์ของการออมกับการลงทุนได้ถูกต้อง","a":"การออมกับการลงทุนไม่เกี่ยวข้องกัน","b":"ยิ่งออมมาก เศรษฐกิจยิ่งแย่ลง","c":"การลงทุนทำให้ไม่มีใครต้องออม","d":"เงินออมถูกนำไปให้กู้ลงทุน เศรษฐกิจเติบโต","correct":3,"explain":"สไลด์ระบุว่าเงินออมในสถาบันการเงินถูกนำไปให้กู้เพื่อลงทุน ทำให้เกิดการผลิต การจ้างงาน และเศรษฐกิจเติบโต"},{"text":"ป้าต้องการออมเงินระยะยาว และมีความเสี่ยงต่ำ ควรเลือกแบบใดดีที่สุด","a":"ซื้อพันธบัตรรัฐบาล","b":"ซื้อของตามกระแส","c":"เก็บเงินไว้ในกระเป๋า","d":"ให้เพื่อนยืมโดยไม่มีหลักฐาน","correct":0,"explain":"พันธบัตรรัฐบาลคือการให้รัฐบาลกู้เงิน ความเสี่ยงต่ำ ได้ดอกเบี้ยตามกำหนด และถือระยะยาว จึงตรงกับความต้องการของป้าที่สุด"}]},{"id":"exam-soc-19","name":"สังคม ม.2 · เรื่องที่ 19 ปัญหาการออมและการลงทุน","subject":"สังคมศึกษา","unit":"หน่วยที่ 11 การออมและการลงทุน · แผนที่ 19","questions":[{"text":"แชร์ลูกโซ่นำเงินจากที่ใดมาจ่ายให้สมาชิกเก่า","a":"กำไรจากการขายสินค้า","b":"เงินของสมาชิกใหม่","c":"ดอกเบี้ยจากธนาคาร","d":"เงินช่วยเหลือจากรัฐ","correct":1,"explain":"แชร์ลูกโซ่นำเงินของสมาชิกใหม่มาจ่ายสมาชิกเก่า เมื่อหาสมาชิกใหม่ไม่ได้ก็ล้ม"},{"text":"ถ้ามีคนชวนลงทุน ควรตรวจสอบกับหน่วยงานใด","a":"อย.","b":"สมอ.","c":"สคบ.","d":"ก.ล.ต.","correct":3,"explain":"ให้ตรวจสอบผู้ชวนลงทุนกับ ก.ล.ต. (1207)"},{"text":"ข้อใดเป็นสาเหตุที่ทำให้คนออมเงินได้น้อย","a":"ใช้จ่ายเกินตัวและตามกระแส","b":"ทำบัญชีรายรับรายจ่ายทุกวัน","c":"ตั้งเป้าหมายการออมชัดเจน","d":"ออมก่อนใช้ทุกเดือน","correct":0,"explain":"สาเหตุที่ออมน้อย คือ รายได้ไม่พอรายจ่าย ค่าครองชีพสูง ใช้จ่ายเกินตัวและตามกระแส ไม่ทำบัญชี ไม่ตั้งเป้าหมาย ส่วนข้ออื่นเป็นวิธีป้องกัน"},{"text":"หนี้ครัวเรือนทำให้การออมลดลง เพราะเหตุใด","a":"ธนาคารไม่รับฝากเงินคนมีหนี้","b":"หนี้ทำให้รายได้เพิ่มขึ้น","c":"เงินที่ควรออมต้องนำไปจ่ายหนี้","d":"คนมีหนี้ไม่ต้องใช้จ่ายอะไร","correct":2,"explain":"สไลด์ระบุว่าเมื่อมีหนี้ครัวเรือน เงินที่ควรออมต้องไปจ่ายหนี้"},{"text":"เมื่อแชร์ลูกโซ่หาสมาชิกใหม่ไม่ได้ จะเกิดอะไรขึ้น","a":"ได้กำไรมากขึ้นกว่าเดิม","b":"รัฐบาลจ่ายเงินคืนแทน","c":"กลายเป็นธุรกิจจริง","d":"แชร์ล้ม สมาชิกเสียเงิน","correct":3,"explain":"แชร์ลูกโซ่ต้องใช้เงินสมาชิกใหม่จ่ายสมาชิกเก่า เมื่อหาสมาชิกใหม่ไม่ได้จึงล้ม"},{"text":"มีคนชวนว่า “ได้ผลตอบแทนสูงมากในเวลาสั้น แค่ชวนเพื่อนมาเพิ่ม” นี่เป็นสัญญาณของอะไร","a":"เงินฝากประจำ","b":"พันธบัตรรัฐบาล","c":"แชร์ลูกโซ่","d":"สหกรณ์ออมทรัพย์","correct":2,"explain":"สัญญาณแชร์ลูกโซ่ คือ ผลตอบแทนสูงเกินจริงในเวลาสั้น ให้ชวนสมาชิกเพิ่ม ไม่มีสินค้าหรือธุรกิจจริง ไม่มีใบอนุญาต"},{"text":"ถ้าพบแชร์ลูกโซ่ ควรแจ้งหน่วยงานใด","a":"กรมสอบสวนคดีพิเศษ หรือตำรวจ","b":"เจ้าของร้านค้าในชุมชน","c":"เพื่อนสมาชิกที่ลงทุนด้วยกัน","d":"ผู้ชักชวนให้ลงทุนคนนั้น","correct":0,"explain":"พบแชร์ลูกโซ่ให้แจ้งกรมสอบสวนคดีพิเศษ (1202) หรือตำรวจ"},{"text":"นายบีกู้เงินมาซื้อทองคำตามเพื่อน โดยไม่ศึกษาความเสี่ยง มีโอกาสเกิดผลอย่างไร","a":"ได้กำไรแน่นอน","b":"ไม่มีความเสี่ยงเลย","c":"ได้รับเงินคืนจากรัฐ","d":"อาจขาดทุนและเป็นหนี้","correct":3,"explain":"ปัญหาการลงทุนโดยขาดความรู้ คือ ลงทุนตามคนอื่น ไม่ศึกษาความเสี่ยง ใช้เงินกู้มาลงทุน ทำให้ขาดทุนและเป็นหนี้"},{"text":"ข้อใดรวมแนวทางป้องกันปัญหาการออมได้ถูกต้อง","a":"ทำบัญชี ออมก่อนใช้ แยกจำเป็นกับต้องการ","b":"ใช้ก่อนออม ซื้อตามกระแส ไม่ต้องจดบัญชี","c":"กู้นอกระบบ ผ่อนสินค้า ใช้บัตรเครดิตเต็มวงเงิน","d":"ไม่ตั้งเป้าหมาย ใช้เงินตามอารมณ์","correct":0,"explain":"แนวทางป้องกันการออม คือ ทำบัญชีรายรับรายจ่าย ออมก่อนใช้ แยกความจำเป็นกับความต้องการ และไม่กู้เกินกำลังผ่อน"},{"text":"เพื่อน 4 คนกำลังจะลงทุน ใครตัดสินใจดีที่สุด","a":"ส้ม ลงทุนกับคนที่บอกว่ารวยใน 7 วัน","b":"ภูมิ ศึกษาก่อน และตรวจสอบกับ ก.ล.ต.","c":"แก้ม กู้เงินมาลงทุนตามเพื่อน","d":"นนท์ ชวนญาติเข้าร่วมเพื่อได้ค่าตอบแทน","correct":1,"explain":"ภูมิทำถูกต้อง เพราะแนวทางป้องกันการลงทุน คือ ศึกษาก่อนลงทุน ไม่ลงทุนด้วยเงินกู้ และตรวจสอบกับ ก.ล.ต. สไลด์เตือนว่า “รวยเร็วเกินจริงคือสัญญาณหลอก”"}]},{"id":"exam-soc-20","name":"สังคม ม.2 · เรื่องที่ 20 การบริหารเงินในครัวเรือน","subject":"สังคมศึกษา","unit":"หน่วยที่ 11 การออมและการลงทุน · แผนที่ 20","questions":[{"text":"การแบ่งเงินแบบ 50 / 30 / 20 ส่วนร้อยละ 20 ใช้ทำอะไร","a":"จำเป็น","b":"อยากได้","c":"ออม","d":"เสียภาษี","correct":2,"explain":"แบ่งเงิน 50/30/20 คือ ร้อยละ 50 จำเป็น · ร้อยละ 30 อยากได้ · ร้อยละ 20 ออม"},{"text":"ยอดคงเหลือในบัญชีรายรับ–รายจ่าย คำนวณอย่างไร","a":"รายจ่าย − รายรับ","b":"รายรับ − รายจ่าย","c":"รายรับ + รายจ่าย","d":"รายรับ × รายจ่าย","correct":1,"explain":"คงเหลือ = รายรับ − รายจ่าย"},{"text":"หลัก “ออมก่อนใช้” หมายถึงข้อใด","a":"ใช้ให้หมดก่อน เหลือค่อยออม","b":"ออมเฉพาะตอนสิ้นปี","c":"ออมเมื่อมีคนบอกให้ออม","d":"ได้รับเงินแล้วแบ่งออมทันที","correct":3,"explain":"หลักการวางแผนออมข้อ 2 คือ ออมก่อนใช้ เมื่อได้รับเงินให้แบ่งออมทันที"},{"text":"ข้อใดเป็นรายจ่ายจำเป็น","a":"ค่าเดินทางไปโรงเรียน","b":"ขนมและเครื่องดื่ม","c":"ของตามกระแส","d":"เกมออนไลน์","correct":0,"explain":"รายจ่ายจำเป็น ได้แก่ อาหาร ค่าเช่าบ้าน ค่าน้ำค่าไฟ ค่าเดินทาง ค่าเล่าเรียน ส่วนขนม ของตามกระแส เกมออนไลน์เป็นรายจ่ายไม่จำเป็น"},{"text":"“อย่าใส่ไข่ไว้ในตะกร้าใบเดียว” หมายความว่าอย่างไร","a":"เก็บเงินไว้ที่เดียวให้หมด","b":"ห้ามซื้อไข่ไก่เก็บไว้","c":"แบ่งเงินไว้หลายรูปแบบ","d":"ใช้เงินให้หมดทุกเดือน","correct":2,"explain":"การกระจายความเสี่ยง คือ แบ่งเงินไว้หลายรูปแบบ เมื่อรูปแบบหนึ่งเสียหาย ส่วนอื่นยังอยู่"},{"text":"ครอบครัวมีรายจ่ายจำเป็นเดือนละ 10,000 บาท ควรมีเงินสำรองฉุกเฉินเท่าไร","a":"1,000–5,000 บาท","b":"30,000–60,000 บาท","c":"10,000–20,000 บาท","d":"100,000–200,000 บาท","correct":1,"explain":"เงินสำรองฉุกเฉินควรมี 3–6 เท่าของรายจ่ายจำเป็นต่อเดือน คือ 10,000 × 3 = 30,000 ถึง 10,000 × 6 = 60,000 บาท"},{"text":"มีเงิน 1,000 บาท แบ่งแบบ 50 / 30 / 20 ส่วนที่ต้องออมคือกี่บาท","a":"500 บาท","b":"300 บาท","c":"100 บาท","d":"200 บาท","correct":3,"explain":"ส่วนออมคือร้อยละ 20 ของ 1,000 บาท = 200 บาท (จำเป็น 500 · อยากได้ 300)"},{"text":"จดบัญชีแล้วพบว่าใช้เงินซื้อชานมไข่มุกเดือนละมาก ข้อมูลนี้ช่วยอะไร","a":"เห็น “รูรั่ว” ของเงิน จะได้ลดลง","b":"ทำให้รายได้เพิ่มขึ้นทันที","c":"ทำให้ไม่ต้องจ่ายค่าเดินทาง","d":"ไม่ได้ช่วยอะไรเลย","correct":0,"explain":"ประโยชน์ของบัญชีรายรับ–รายจ่าย คือ รู้ว่าเงินใช้ไปกับอะไร และเห็น “รูรั่ว” ของเงิน ชานมไข่มุกเป็นรายจ่ายไม่จำเป็นที่ลดได้"},{"text":"ข้อใดจับคู่ “ตะกร้า” กับที่เก็บเงินได้ถูกต้อง","a":"ฉุกเฉิน–พันธบัตร · ระยะกลาง–ออมทรัพย์ · ระยะยาว–ฝากประจำ","b":"ฉุกเฉิน–ออมทรัพย์ · ระยะกลาง–ฝากประจำ · ระยะยาว–พันธบัตร","c":"ฉุกเฉิน–ฝากประจำ · ระยะกลาง–พันธบัตร · ระยะยาว–ออมทรัพย์","d":"ฉุกเฉิน–แชร์ลูกโซ่ · ระยะกลาง–ซื้อของ · ระยะยาว–เล่นเกม","correct":1,"explain":"สไลด์แบ่งเงิน 3 ตะกร้า คือ ฉุกเฉิน = เงินฝากออมทรัพย์ (ถอนง่าย) · ระยะกลาง = ฝากประจำหรือสลากออมทรัพย์ · ระยะยาว = พันธบัตรรัฐบาลหรือกองทุนรวม"},{"text":"นักเรียน 4 คนบริหารเงินค่าขนม ใครทำได้ดีที่สุด","a":"มด จดบัญชี ออมก่อนใช้ และตั้งเป้าหมาย","b":"บี ใช้หมดทุกวัน และไม่จดบัญชี","c":"ต้น ออมบ้างไม่ออมบ้าง ไม่มีเป้าหมาย","d":"ฝน ยืมเงินเพื่อนมาซื้อของตามกระแส","correct":0,"explain":"หลักการบริหารเงิน คือ จดบัญชี ตั้งเป้าหมาย ออมก่อนใช้ และทำต่อเนื่อง มดทำได้ครบ ส่วนคนอื่นขัดกับหลักการ"}]},{"id":"exam-soc-21","name":"สังคม ม.2 · เรื่องที่ 21 ระบบเศรษฐกิจและการพึ่งพาในเอเชีย","subject":"สังคมศึกษา","unit":"หน่วยที่ 12 ความสัมพันธ์ทางเศรษฐกิจ · แผนที่ 21","questions":[{"text":"ในระบบสังคมนิยม ใครเป็นเจ้าของปัจจัยการผลิตที่สำคัญ","a":"รัฐ","b":"เอกชน","c":"ต่างชาติ","d":"วัด","correct":0,"explain":"ระบบสังคมนิยม รัฐเป็นเจ้าของปัจจัยการผลิตที่สำคัญ และวางแผนว่าจะผลิตอะไร กำหนดราคา"},{"text":"อาเซียนก่อตั้งขึ้นที่เมืองใด","a":"โตเกียว (ปฏิญญาโตเกียว)","b":"กรุงเทพฯ (ปฏิญญากรุงเทพ)","c":"ปักกิ่ง (ปฏิญญาปักกิ่ง)","d":"สิงคโปร์ (ปฏิญญาสิงคโปร์)","correct":1,"explain":"อาเซียนก่อตั้งเมื่อ 8 ส.ค. 2510 ที่กรุงเทพฯ (ปฏิญญากรุงเทพ)"},{"text":"ประเทศใดใช้ระบบเศรษฐกิจแบบทุนนิยม","a":"เกาหลีเหนือ","b":"คิวบา","c":"ไทย","d":"สหรัฐอเมริกา","correct":3,"explain":"สไลด์ยกตัวอย่างทุนนิยม คือ สหรัฐอเมริกา ญี่ปุ่น สิงคโปร์ · สังคมนิยม คือ เกาหลีเหนือ คิวบา · ผสม คือ ไทย มาเลเซีย อินเดีย"},{"text":"ในระบบทุนนิยม ราคาสินค้ากำหนดโดยอะไร","a":"รัฐเป็นผู้กำหนดราคาทั้งหมด","b":"ผู้นำชุมชนเป็นผู้กำหนด","c":"กลไกตลาด (อุปสงค์–อุปทาน)","d":"การจับสลากของผู้ขาย","correct":2,"explain":"ระบบทุนนิยม เอกชนเป็นเจ้าของปัจจัยการผลิต ราคากำหนดโดยกลไกตลาด (อุปสงค์–อุปทาน) มีการแข่งขัน รัฐแทรกแซงน้อย"},{"text":"ทำไมประเทศต่างๆ ในเอเชียจึงต้องพึ่งพาอาศัยกัน","a":"ไม่มีประเทศใดผลิตทุกอย่างได้เอง","b":"ทุกประเทศมีทรัพยากรเหมือนกัน","c":"กฎหมายบังคับให้ต้องค้าขายกัน","d":"ทุกประเทศใช้ระบบเศรษฐกิจเดียวกัน","correct":0,"explain":"แต่ละประเทศมีทรัพยากร แรงงาน และเทคโนโลยีต่างกัน ไม่มีประเทศใดผลิตทุกอย่างได้เอง จึงต้องพึ่งพากัน"},{"text":"ญี่ปุ่นมาตั้งโรงงานในประเทศไทย เป็นการพึ่งพากันด้านใด","a":"การค้า","b":"การลงทุน","c":"แรงงาน","d":"การท่องเที่ยว","correct":1,"explain":"สไลด์ยกตัวอย่างการพึ่งพาด้านการลงทุนว่า ญี่ปุ่นตั้งโรงงานในไทย"},{"text":"รัฐไทยดูแลไฟฟ้าและประปา แต่เอกชนเปิดร้านค้าได้อย่างเสรี แสดงว่าไทยใช้ระบบใด","a":"ทุนนิยม","b":"สังคมนิยม","c":"ผสม","d":"ไม่มีระบบเศรษฐกิจ","correct":2,"explain":"ระบบผสม คือ เอกชนทำธุรกิจได้อย่างเสรี รัฐดูแลกิจการสาธารณูปโภค และช่วยเหลือเมื่อเกิดปัญหา เช่น ไทย"},{"text":"ระบบสังคมนิยมช่วยลดความเหลื่อมล้ำ แต่มีจุดอ่อนอย่างไร","a":"มีการแข่งขันสูงมาก","b":"เอกชนเป็นเจ้าของทุกอย่าง","c":"รัฐไม่วางแผนการผลิตเลย","d":"มีการแข่งขันน้อย","correct":3,"explain":"สไลด์ระบุว่าสังคมนิยมลดความเหลื่อมล้ำ แต่แข่งขันน้อย ส่วนตัวเลือกอื่นเป็นลักษณะของทุนนิยมหรือผิดจากความจริง"},{"text":"ไทยเข้าร่วมอาเซียนและเอเปก สรุปผลต่อไทยได้อย่างไร","a":"ได้ประโยชน์อย่างเดียว ไม่มีผลเสียใดๆ เลย","b":"ได้ตลาดใหญ่ขึ้น แต่ต้องแข่งกับสินค้าต่างชาติ","c":"เสียประโยชน์อย่างเดียว ไม่มีผลดีใดๆ เลย","d":"ไม่เกิดผลใดๆ ต่อเศรษฐกิจไทยเลย","correct":1,"explain":"เมื่อรวมข้อดี (ตลาดใหญ่ขึ้น ภาษีลดลง ลงทุนเพิ่ม) กับข้อควรระวัง (สินค้าต่างประเทศเข้ามาแข่ง ได้รับผลเมื่อคู่ค้ามีปัญหา) จะสรุปได้ว่ามีทั้งผลดีและสิ่งที่ต้องระวัง"},{"text":"ข้อใดเป็นความคิดที่เหมาะสมที่สุดต่อการพึ่งพาทางเศรษฐกิจระหว่างประเทศ","a":"ปิดประเทศ ผลิตทุกอย่างเอง","b":"ไม่ค้าขายกับประเทศที่ต่างระบบ","c":"ร่วมมือกันเพื่อเติบโตไปด้วยกัน","d":"แข่งขันจนอีกฝ่ายล้มละลาย","correct":2,"explain":"สไลด์สรุปข้อคิดว่า ระบบต่างกันได้ แต่ไม่มีประเทศใดอยู่ได้ลำพัง ร่วมมือกันจึงเติบโตไปด้วยกัน"}]},{"id":"exam-soc-22","name":"สังคม ม.2 · เรื่องที่ 22 ทรัพยากรโลกและการแข่งขันทางการค้า","subject":"สังคมศึกษา","unit":"หน่วยที่ 12 ความสัมพันธ์ทางเศรษฐกิจ · แผนที่ 22","questions":[{"text":"ประเทศใดมีทรัพยากรน้ำมันมาก","a":"บราซิล","b":"ซาอุดีอาระเบีย","c":"ออสเตรเลีย","d":"รัสเซีย","correct":1,"explain":"สไลด์ระบุว่า น้ำมัน = ซาอุดีอาระเบีย · ทองคำ = จีน ออสเตรเลีย · ป่าไม้ = บราซิล รัสเซีย"},{"text":"มาตรการที่จำกัดปริมาณสินค้านำเข้า เรียกว่าอะไร","a":"กำแพงภาษี","b":"การค้าเสรี","c":"โควตา","d":"การส่งออก","correct":2,"explain":"โควตา คือ การจำกัดปริมาณนำเข้า เป็นมาตรการของการค้าแบบคุ้มกัน"},{"text":"“การค้าเสรี” คืออะไร","a":"ลดหรือยกเลิกภาษีและอุปสรรคทางการค้า","b":"ห้ามนำเข้าสินค้าทุกชนิด","c":"ให้รัฐเป็นเจ้าของทุกบริษัท","d":"เก็บภาษีสินค้าทุกชิ้นเพิ่มขึ้น","correct":0,"explain":"การค้าเสรี คือ ลดหรือยกเลิกภาษีและอุปสรรคทางการค้า ทำให้สินค้าหลากหลาย ราคาถูก แต่ผู้ผลิตในประเทศต้องแข่งขันสูง"},{"text":"ทำไมแต่ละประเทศจึงต้องค้าขายระหว่างประเทศ","a":"ทุกประเทศมีทรัพยากรเท่ากัน","b":"อยากให้สินค้าในประเทศแพงขึ้น","c":"ต้องการลดการผลิตในประเทศ","d":"ทรัพยากรต่างกัน จึงแลกสิ่งที่ตนขาด","correct":3,"explain":"ทรัพยากร ภูมิอากาศ แรงงาน ทุน เทคโนโลยีต่างกัน จึงส่งออกสิ่งที่ผลิตได้ดี และนำเข้าสิ่งที่ขาด"},{"text":"การค้าแบบคุ้มกันมีเป้าหมายเพื่ออะไร","a":"ให้สินค้าต่างชาติเข้ามาได้มากขึ้น","b":"ปกป้องผู้ผลิตในประเทศ","c":"ยกเลิกภาษีนำเข้าทั้งหมด","d":"ทำให้สินค้านำเข้าราคาถูกลง","correct":1,"explain":"การค้าแบบคุ้มกันมีไว้ปกป้องผู้ผลิตในประเทศ ด้วยกำแพงภาษี โควตา และมาตรการที่มิใช่ภาษี"},{"text":"ประเทศหนึ่งเก็บภาษีศุลกากรสูงกับรถยนต์ที่นำเข้า เป็นนโยบายแบบใด","a":"การค้าแบบคุ้มกัน","b":"การค้าเสรี","c":"ระบบสังคมนิยม","d":"การรวมกลุ่มอาเซียน","correct":0,"explain":"กำแพงภาษี (ภาษีศุลกากร) เป็นมาตรการของการค้าแบบคุ้มกัน"},{"text":"ทุเรียนไทยแข่งกับทุเรียนเวียดนามในตลาดจีน เป็นการแข่งขันแบบใด","a":"การแข่งขันในประเทศ","b":"การแข่งขันต่างประเทศ","c":"ไม่ใช่การแข่งขัน","d":"การค้าแบบคุ้มกัน","correct":1,"explain":"สไลด์ยกตัวอย่างการแข่งขันต่างประเทศว่า ทุเรียนไทยแข่งกับเวียดนามในตลาดจีน ส่วนในประเทศ เช่น ร้านสะดวกซื้อ ค่ายโทรศัพท์มือถือ"},{"text":"ร้านสะดวกซื้อหลายรายแข่งกันแย่งลูกค้า ผู้บริโภคได้รับผลอย่างไร","a":"สินค้าแย่ลง และราคาแพงขึ้นกว่าเดิม","b":"มีสินค้าให้เลือกน้อยลงกว่าเดิม","c":"สินค้าดีขึ้น ราคาถูกลง มีให้เลือกมาก","d":"ไม่เกิดผลใดๆ ต่อผู้บริโภคเลย","correct":2,"explain":"การแข่งขันทางการค้าทำให้คุณภาพดีขึ้น ราคาถูกลง และมีสินค้าหลากหลายขึ้น"},{"text":"ข้อใดสรุปเรื่องทรัพยากรโลกกับการแข่งขันทางการค้าได้ถูกต้อง","a":"ทรัพยากรเท่ากัน จึงไม่ต้องค้าขายกันเลย","b":"ยิ่งแข่งขันกันมาก สินค้ายิ่งแย่ลงเรื่อยๆ","c":"ไม่ต้องค้าขายก็มีสินค้าครบทุกอย่างแล้ว","d":"ทรัพยากรไม่เท่ากันจึงค้าขาย แข่งกันจึงดีขึ้น","correct":3,"explain":"สไลด์สรุปข้อคิดว่า ทรัพยากรไม่เท่ากันจึงต้องค้าขาย แข่งกันสินค้าจึงดีขึ้น และผู้บริโภคต้องเลือกซื้ออย่างรู้เท่าทัน"},{"text":"รถยนต์ไฟฟ้าจีนเข้ามาขายในไทย ผู้ผลิตไทยควรทำอย่างไรจึงเหมาะสมที่สุด","a":"ไม่ทำอะไร รอลูกค้ากลับมาเอง","b":"ขึ้นราคาให้สูงกว่าเดิมมาก","c":"ปรับตัว พัฒนาสินค้าให้ดีขึ้น","d":"ลดคุณภาพเพื่อให้ต้นทุนต่ำ","correct":2,"explain":"สไลด์ระบุว่าการแข่งขันทำให้คุณภาพดีขึ้น แต่ผู้ที่ปรับตัวไม่ได้อาจขาดทุนหรือปิดกิจการ การปรับตัวและพัฒนาสินค้าจึงเหมาะสมที่สุด"}]},{"id":"exam-his-01","name":"ประวัติ ม.2 · เรื่องที่ 1 การกู้เอกราชและการสถาปนาอาณาจักรธนบุรี","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 5 พัฒนาการของอาณาจักรธนบุรี · เรื่องที่ ๑","questions":[{"text":"พระยาตากตีฝ่าวงล้อมจากค่ายใด","a":"วัดลุ่ม","b":"โพธิ์สามต้น","c":"วัดพิชัย","d":"ป้อมวิไชยประสิทธิ์","correct":2,"explain":"พระยาตากตีฝ่าวงล้อมพม่าออกจากค่ายวัดพิชัย"},{"text":"เมืองใดเป็นฐานที่มั่น ต่อเรือรบ","a":"จันทบุรี","b":"ระยอง","c":"ธนบุรี","d":"โพธิ์สามต้น","correct":0,"explain":"ยึดจันทบุรีเป็นฐานที่มั่นและต่อเรือรบประมาณ ๑๐๐ ลำ ส่วนระยองรวบรวมผู้คนและเสบียง"},{"text":"ราชธานีของพระยาตากชื่อใด","a":"กรุงเทพมหานคร","b":"กรุงรัตนโกสินทร์","c":"กรุงศรีอยุธยา","d":"กรุงธนบุรีศรีมหาสมุทร","correct":3,"explain":"ปราบดาภิเษก ๒๘ ธ.ค. ๒๓๑๐ ตั้งราชธานีชื่อ “กรุงธนบุรีศรีมหาสมุทร”"},{"text":"“ทุบหม้อข้าว” หมายถึงอะไร","a":"ให้รีบกินข้าว","b":"ให้ทุกคนมุ่งรบ","c":"ให้ทุกคนหยุดพัก","d":"ให้ทุกคนกลับบ้าน","correct":1,"explain":"ตามเรื่องเล่า ทุบหม้อข้าวเพื่อให้ทุกคนมุ่งรบ"},{"text":"ธนบุรีใกล้ทะเล ดีอย่างไร","a":"มีกำแพงสูงไว้ป้องกัน","b":"อยู่ไกลจากศัตรูมากที่สุด","c":"สร้างป้อมใหม่ได้ทันที","d":"ค้าขายและรับเสบียงสะดวก","correct":3,"explain":"ธนบุรีอยู่ปากแม่น้ำเจ้าพระยา ค้าขายและรับเสบียงสะดวก"},{"text":"สู้พม่าไม่ไหว ควรถอยไปทางใด","a":"ทางบกไปอยุธยา","b":"ไปค่ายวัดพิชัย","c":"ทางเรือไปจันทบุรี","d":"ไปโพธิ์สามต้น","correct":2,"explain":"ธนบุรีถอยทางเรือได้ หากสู้ไม่ได้ยังไปจันทบุรีทางทะเลได้"},{"text":"ควรเลือกเมืองแบบใดเป็นที่มั่น","a":"เมืองใหญ่ ไม่มีป้อม","b":"เมืองเล็ก มีป้อม ใกล้ทะเล","c":"เมืองใหญ่ ถูกทำลายมาก","d":"เมืองไกลทะเล ไม่มีแม่น้ำ","correct":1,"explain":"เหตุผลที่เลือกธนบุรี: เมืองเล็กป้องกันง่าย มีป้อมเดิม ใกล้ทะเล"},{"text":"ระยองกับจันทบุรี ต่างกันอย่างไร","a":"ระยองต่อเรือ จันทบุรีรวบรวมคน","b":"ระยองรวบรวมคน จันทบุรีต่อเรือ","c":"ทั้งสองเป็นที่ปราบดาภิเษก","d":"ทั้งสองเป็นที่ขับพม่า","correct":1,"explain":"ระยองรวบรวมผู้คนและเสบียง ส่วนจันทบุรีเป็นฐานที่มั่นและต่อเรือรบ"},{"text":"เส้นทางกู้เอกราชเรียงอย่างไรถูกต้อง","a":"วัดพิชัย → จันทบุรี → ระยอง → โพธิ์สามต้น → ธนบุรี","b":"วัดพิชัย → ระยอง → โพธิ์สามต้น → จันทบุรี → ธนบุรี","c":"วัดพิชัย → ระยอง → จันทบุรี → โพธิ์สามต้น → ธนบุรี","d":"ระยอง → วัดพิชัย → จันทบุรี → โพธิ์สามต้น → ธนบุรี","correct":2,"explain":"สไลด์เรียง ๑ วัดพิชัย ๒ ระยอง ๓ จันทบุรี ๔ โพธิ์สามต้น ๕ ธนบุรี"},{"text":"สองเล่มบอกปีไม่ตรงกัน ควรทำอย่างไร","a":"เทียบหลายแหล่งก่อนสรุป","b":"เชื่อเล่มที่อ่านก่อนเลย","c":"เลือกปีที่จำง่ายที่สุด","d":"ไม่ต้องสนใจเรื่องปีเลย","correct":0,"explain":"สไลด์ “ข้อควรรู้” ระบุว่านักประวัติศาสตร์ต้องเทียบหลายแหล่งก่อนสรุป"}]},{"id":"exam-his-02","name":"ประวัติ ม.2 · เรื่องที่ 2 การเมืองการปกครอง สังคม เศรษฐกิจ และการสิ้นสุดสมัยธนบุรี","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 5 · เรื่องที่ ๒","questions":[{"text":"ชุมนุมสุดท้ายที่ถูกปราบคือชุมนุมใด","a":"เจ้านครศรีธรรมราช","b":"เจ้าพระฝาง","c":"เจ้าพิมาย","d":"เจ้าพระยาพิษณุโลก","correct":1,"explain":"ชุมนุมเจ้าพระฝาง (พ.ศ. ๒๓๑๓) ปราบได้เป็นชุมนุมสุดท้าย"},{"text":"สมุหพระกลาโหมดูแลฝ่ายใด","a":"ฝ่ายพลเรือน","b":"ฝ่ายการคลัง","c":"ฝ่ายศาสนา","d":"ฝ่ายทหาร","correct":3,"explain":"สมุหนายกดูแลฝ่ายพลเรือน สมุหพระกลาโหมดูแลฝ่ายทหาร"},{"text":"จตุสดมภ์ฝ่ายใดดูแลความสงบเมืองหลวง","a":"เวียง","b":"วัง","c":"คลัง","d":"นา","correct":0,"explain":"เวียง = นครบาล ดูแลความสงบในเมืองหลวง"},{"text":"ทำไมต้องสักข้อมือไพร่หลวง","a":"เพื่อเก็บภาษีสำเภา","b":"เพื่อแบ่งชนชั้น","c":"เพื่อสะดวกเกณฑ์ไปรบ","d":"เพื่อให้พระสงฆ์รู้จัก","correct":2,"explain":"สักข้อมือเพื่อสะดวกในการเกณฑ์ไปรบ เพราะบ้านเมืองอยู่ในภาวะสงคราม"},{"text":"“ข้าวยากหมากแพง” คืออะไร","a":"ข้าวมากจนขายไม่ได้","b":"ไม่ยอมเสียภาษี","c":"การค้ากับจีนหยุด","d":"ข้าวหายาก ราคาแพง","correct":3,"explain":"ข้าวยากหมากแพงคือปัญหาหลังสงคราม ข้าวและของกินหายากและราคาสูง"},{"text":"คนหิวทันที ควรแก้ปัญหาอย่างไร","a":"ปลูกข้าวรอเก็บเกี่ยว","b":"ซื้อข้าวสารมาแจก","c":"เก็บภาษีเพิ่มขึ้น","d":"ปิดการค้าต่างประเทศ","correct":1,"explain":"วิธีระยะสั้นคือใช้พระราชทรัพย์ซื้อข้าวสารจากเรือสำเภามาแจกราษฎร"},{"text":"ใครเป็นชนชั้นใต้ปกครอง","a":"เจ้านาย","b":"ขุนนาง","c":"ไพร่","d":"พระมหากษัตริย์","correct":2,"explain":"ชนชั้นใต้ปกครองคือไพร่และทาส"},{"text":"ข้อใดจับคู่ชุมนุมกับสิ่งที่ได้ถูกต้อง","a":"เจ้าพิมาย – หัวเมืองฝ่ายเหนือ","b":"เจ้านครฯ – หัวเมืองฝ่ายใต้","c":"เจ้าพระฝาง – อีสานตอนล่าง","d":"เจ้าพิษณุโลก – หัวเมืองฝ่ายใต้","correct":1,"explain":"เจ้านครฯ ได้หัวเมืองฝ่ายใต้ เจ้าพิมายได้อีสานตอนล่าง เจ้าพระฝางได้หัวเมืองฝ่ายเหนือ"},{"text":"ปราบครบทุกชุมนุมแล้วเกิดผลอย่างไร","a":"รวมแผ่นดินเป็นหนึ่งเดียว","b":"เสียหัวเมืองใต้ให้พม่า","c":"แบ่งแผ่นดินเป็นสองส่วน","d":"ชุมนุมยังเป็นอิสระ","correct":0,"explain":"ปราบครบทุกชุมนุมแล้ว รวมแผ่นดินเป็นหนึ่งเดียวสำเร็จ"},{"text":"ใช้แบบอยุธยาตอนปลายปกครอง เหมาะสมไหม","a":"ไม่เหมาะ ควรสร้างระบบใหม่","b":"ไม่เหมาะ เพราะอยุธยาล่มแล้ว","c":"เหมาะ เพราะฟื้นฟูบ้านเมือง","d":"เหมาะ เพราะไม่ต้องมีจตุสดมภ์","correct":2,"explain":"ธนบุรียึดแบบอยุธยาตอนปลาย เพราะเป็นช่วงฟื้นฟูบ้านเมืองหลังสงคราม"}]},{"id":"exam-his-03","name":"ประวัติ ม.2 · เรื่องที่ 3 มิตรและศึกของกรุงธนบุรี","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 5 · เรื่องที่ ๓","questions":[{"text":"ศึกอะแซหวุ่นกี้ ทำกับชาติใด","a":"ล้านช้าง","b":"เขมร","c":"พม่า","d":"จีน","correct":2,"explain":"ศึกอะแซหวุ่นกี้ (พ.ศ. ๒๓๑๘) ทำกับพม่า เป็นสงครามใหญ่ที่สุดสมัยธนบุรี"},{"text":"พระยาพิชัยดาบหัก ดังจากศึกใด","a":"ศึกเมืองพิชัย","b":"ศึกบางกุ้ง","c":"ศึกอะแซหวุ่นกี้","d":"ศึกเวียงจันทน์","correct":0,"explain":"ศึกเมืองพิชัย พ.ศ. ๒๓๑๖ เกี่ยวข้องกับพระยาพิชัยดาบหัก"},{"text":"ตีเวียงจันทน์ ได้พระพุทธรูปใดมา","a":"พระแก้วมรกต พระพุทธชินราช","b":"พระบาง พระพุทธชินราช","c":"พระพุทธสิหิงค์ พระบาง","d":"พระแก้วมรกต พระบาง","correct":3,"explain":"ตีเวียงจันทน์แล้วอัญเชิญพระแก้วมรกตและพระบางมากรุงธนบุรี"},{"text":"จีนไม่รับรองในระยะแรก เพราะอะไร","a":"ไม่เคยส่งสำเภาไปค้าที่จีน","b":"ไม่ใช่เชื้อสายกษัตริย์เดิม","c":"ธนบุรีตีเขมรได้ก่อนจีน","d":"ธนบุรีไม่มีปืนคาบศิลา","correct":1,"explain":"จีนสมัยชิงไม่รับรอง เพราะไม่ได้สืบเชื้อสายจากกษัตริย์องค์ก่อน"},{"text":"ล้านนาอยู่ในอำนาจธนบุรีได้อย่างไร","a":"ส่งสำเภามาค้า","b":"ถวายปืนคาบศิลา","c":"เกิดกบฏในเชียงใหม่","d":"ธนบุรีตีเชียงใหม่จากพม่า","correct":3,"explain":"พ.ศ. ๒๓๑๗ ธนบุรียกทัพตีเชียงใหม่จากพม่า ล้านนาจึงอยู่ในอำนาจธนบุรี"},{"text":"อยากได้ปืนรบพม่า ควรติดต่อชาติใด","a":"โปรตุเกสและเขมร","b":"ฮอลันดาและอังกฤษ","c":"จีนและล้านนา","d":"ล้านช้างและมลายู","correct":1,"explain":"ฮอลันดาถวายปืนคาบศิลา อังกฤษถวายปืนนกสับ"},{"text":"ใครช่วยควบคุมหัวเมืองมลายู","a":"เมืองเชียงใหม่","b":"เมืองจันทบุรี","c":"เมืองนครศรีธรรมราช","d":"เมืองพิษณุโลก","correct":2,"explain":"หัวเมืองมลายูถูกควบคุมผ่านเมืองนครศรีธรรมราช"},{"text":"ธนบุรีกับล้านนา เขมร ข้อใดถูก","a":"ล้านนาเป็นประเทศราช เขมรตีจากพม่า","b":"ตีล้านนาจากพม่า เขมรเป็นประเทศราช","c":"ทั้งสองเกิดกบฏปีเดียวกัน","d":"ทั้งสองส่งสำเภามาค้า","correct":1,"explain":"ธนบุรีตีเชียงใหม่จากพม่า (๒๓๑๗) ส่วนเขมรเป็นประเทศราช (๒๓๑๔)"},{"text":"ธนบุรีสัมพันธ์กับ ๓ กลุ่มอย่างไร","a":"ทำสงครามกับทุกกลุ่มประเทศเหมือนกัน","b":"ค้าขายกับทุกกลุ่มและไม่เคยรบกับใคร","c":"รบเพื่อนบ้าน ค้าจีน ค้าและอาวุธตะวันตก","d":"ปิดประเทศ ไม่ติดต่อกับกลุ่มใดเลยตลอด","correct":2,"explain":"รัฐเพื่อนบ้าน (สงคราม การเมือง) จีน (ค้าสำเภา) ชาติตะวันตก (ค้าและอาวุธ)"},{"text":"จีนยังไม่รับรอง แต่ค้าต่อ เหมาะไหม","a":"เหมาะ ได้ข้าวและรายได้","b":"เหมาะ จีนรับรองทันที","c":"ไม่เหมาะ ต้องรอรับรอง","d":"ไม่เหมาะ จีนเป็นศัตรู","correct":0,"explain":"การค้าสำเภาได้สินค้า ข้าว และรายได้ ช่วยฟื้นฟูเศรษฐกิจหลังสงคราม"}]},{"id":"exam-his-04","name":"ประวัติ ม.2 · เรื่องที่ 4 ภูมิปัญญา ศิลปกรรม ดนตรีและนาฏศิลป์สมัยอยุธยาและธนบุรี","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 6 ภูมิปัญญาและศิลปวัฒนธรรมไทย · เรื่องที่ ๑","questions":[{"text":"ตำราพระโอสถพระนารายณ์ เป็นภูมิปัญญาด้านใด","a":"การเกษตร","b":"การแพทย์","c":"สถาปัตยกรรม","d":"ดนตรี","correct":1,"explain":"ตำราพระโอสถพระนารายณ์รวบรวมตำรับยาสมุนไพรแผนไทย จึงเป็นภูมิปัญญาด้านการแพทย์"},{"text":"พระมงคลบพิตร เป็นงานศิลปกรรมประเภทใด","a":"สถาปัตยกรรม","b":"นาฏศิลป์","c":"ประติมากรรม","d":"วรรณกรรม","correct":2,"explain":"สไลด์จัดพระมงคลบพิตร (พระพุทธรูปทรงเครื่อง) เป็นงานประติมากรรมสมัยอยุธยา"},{"text":"ข้อใดเป็นวงดนตรีไทยสมัยอยุธยา","a":"วงโยธวาทิต","b":"วงออร์เคสตรา","c":"วงดนตรีสากล","d":"วงปี่พาทย์","correct":3,"explain":"ดนตรีสมัยอยุธยามีวงปี่พาทย์ วงเครื่องสาย และวงมโหรี"},{"text":"สมัยอยุธยาขุดคลองเพื่อประโยชน์ใด","a":"คมนาคมและชลประทาน","b":"เลี้ยงสัตว์น้ำอย่างเดียว","c":"กั้นพรมแดนกับจีน","d":"ทำเป็นที่พักผ่อน","correct":0,"explain":"สไลด์ภูมิปัญญาด้านการเกษตรระบุว่า อยุธยาขุดคลองเพื่อคมนาคมและชลประทาน"},{"text":"ชาวอยุธยาปลูกข้าวฟางลอย เพราะเหตุใด","a":"เพราะเป็นข้าวที่ปลูกบนภูเขาได้","b":"เพราะปรับตัวตามระดับน้ำได้","c":"เพราะไม่ต้องใช้น้ำเลย","d":"เพราะปลูกเสร็จในวันเดียว","correct":1,"explain":"อยุธยาเป็นที่ราบลุ่มแม่น้ำ จึงปลูกข้าวฟางลอยที่ปรับตัวตามระดับน้ำได้"},{"text":"ถ้าต้องการชมงานช่างที่ธนบุรีปฏิสังขรณ์ ควรไปที่ใด","a":"กำแพงเมืองจีน ประเทศจีน","b":"ทัชมาฮาล ประเทศอินเดีย","c":"วัดแจ้ง (วัดอรุณราชวราราม)","d":"นครวัด ประเทศกัมพูชา","correct":2,"explain":"สมัยธนบุรีฟื้นฟูงานช่างโดยปฏิสังขรณ์วัดแจ้ง (วัดอรุณราชวราราม) ส่วนตัวเลือกอื่นอยู่ต่างประเทศ"},{"text":"ป้อมวิไชยประสิทธิ์ริมแม่น้ำเจ้าพระยา เป็นภูมิปัญญาสมัยธนบุรีด้านใด","a":"การแพทย์แผนไทย","b":"การป้องกันราชธานี","c":"การปลูกข้าว","d":"ดนตรีไทย","correct":1,"explain":"ภูมิปัญญาสมัยธนบุรี คือ สร้างป้อมปราการ และขุดคูเมือง เพื่อป้องกันราชธานี"},{"text":"ศิลปกรรมสมัยธนบุรีมีน้อย เพราะเหตุใด","a":"ไม่มีช่างฝีมือเหลืออยู่เลย","b":"คนไม่นับถือศาสนาแล้ว","c":"รับศิลปะจากตะวันตกแทน","d":"เป็นช่วงสั้นและอยู่ในภาวะสงคราม","correct":3,"explain":"ธนบุรีมีเพียง 15 ปีและอยู่ในภาวะสงคราม จึงเน้นฟื้นฟูและสืบทอดจากอยุธยา"},{"text":"ข้อใดสรุปศิลปวัฒนธรรมสมัยอยุธยาและธนบุรีได้ถูกต้อง","a":"อยุธยาสร้างสรรค์ ธนบุรีฟื้นฟูและสืบทอด","b":"อยุธยาลอกแบบ ธนบุรีสร้างใหม่ทั้งหมด","c":"ทั้งสองสมัยไม่มีงานศิลปะเลย","d":"ธนบุรียกเลิกศิลปะของอยุธยา","correct":0,"explain":"สไลด์สรุปว่า อยุธยาเป็นยุคสร้างสรรค์ ส่วนธนบุรีเน้นฟื้นฟูและสืบทอดจากอยุธยา"},{"text":"ถ้าจะสร้างเมืองตามภูมิปัญญาแบบอยุธยา ทำเลใดดีที่สุด","a":"บนยอดเขาสูงไกลแม่น้ำ","b":"กลางทะเลทรายแห้งแล้ง","c":"บนเกาะที่มีแม่น้ำล้อมรอบ","d":"ในหุบเขาที่ไม่มีทางน้ำ","correct":2,"explain":"อยุธยาตั้งบนเกาะที่แม่น้ำเจ้าพระยา ป่าสัก ลพบุรีล้อมรอบ ช่วยป้องกันข้าศึก คมนาคมและเพาะปลูกสะดวก ทำเลนี้จึงดีที่สุด"}]},{"id":"exam-his-05","name":"ประวัติ ม.2 · เรื่องที่ 5 วรรณกรรมและประเพณีไทยสมัยอยุธยาและธนบุรี","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 6 ภูมิปัญญาและศิลปวัฒนธรรมไทย · เรื่องที่ ๒","questions":[{"text":"วรรณกรรมใดที่สมเด็จพระเจ้าตากสินทรงพระราชนิพนธ์","a":"ลิลิตยวนพ่าย","b":"รามเกียรติ์","c":"กาพย์เห่เรือ","d":"จินดามณี","correct":1,"explain":"สมเด็จพระเจ้าตากสินทรงพระราชนิพนธ์บทละครเรื่องรามเกียรติ์ (ส่วนลิลิตยวนพ่าย กาพย์เห่เรือ จินดามณี เป็นวรรณกรรมสมัยอยุธยา)"},{"text":"สมัยใดเป็นยุคทองของวรรณคดีอยุธยา","a":"สมเด็จพระบรมไตรโลกนาถ","b":"เจ้าฟ้าธรรมธิเบศร","c":"สมเด็จพระเจ้าตากสิน","d":"สมเด็จพระนารายณ์ฯ","correct":3,"explain":"สมัยสมเด็จพระนารายณ์ฯ เป็นยุคทองของวรรณคดี เช่น จินดามณี สมุทรโฆษคำฉันท์"},{"text":"จินดามณี เป็นหนังสือประเภทใด","a":"ตำรายาสมุนไพร","b":"ตำราพิชัยสงคราม","c":"ตำราเรียนภาษาไทย","d":"บทละครรำ","correct":2,"explain":"จินดามณี แต่งโดยพระโหราธิบดี เป็นตำราเรียนภาษาไทย"},{"text":"พระราชพิธีจรดพระนังคัลแรกนาขวัญ จัดเป็นประเพณีกลุ่มใด","a":"เกี่ยวกับพระพุทธศาสนา","b":"การเกษตรและฤดูกาล","c":"เกี่ยวกับพระมหากษัตริย์","d":"การสงคราม","correct":1,"explain":"จรดพระนังคัลแรกนาขวัญ สงกรานต์ ลอยกระทง เป็นประเพณีการเกษตรและฤดูกาล"},{"text":"ลิลิตยวนพ่าย เล่าเรื่องเกี่ยวกับอะไร","a":"สงครามอยุธยากับล้านนา","b":"การเดินทางไปเมืองจีน","c":"การสร้างกรุงธนบุรี","d":"พระราชพิธีแรกนา","correct":0,"explain":"ลิลิตยวนพ่ายเป็นวรรณกรรมอยุธยาตอนต้น เล่าเรื่องสงครามอยุธยากับล้านนา"},{"text":"ข้อใดเป็นประเพณีกลุ่มเดียวกับ “ทอดกฐิน”","a":"การบวช","b":"สงกรานต์","c":"ลอยกระทง","d":"พยุหยาตราทางชลมารค","correct":0,"explain":"ทอดกฐินอยู่ในกลุ่มประเพณีเกี่ยวกับพระพุทธศาสนา เช่นเดียวกับการบวชและทำบุญตักบาตร"},{"text":"ถ้าต้องการอ่านวรรณกรรมที่แต่งในสมัยธนบุรี ควรเลือกเรื่องใด","a":"มหาชาติคำหลวง","b":"สมุทรโฆษคำฉันท์","c":"นิราศกวางตุ้ง","d":"กาพย์เห่เรือ","correct":2,"explain":"นิราศกวางตุ้ง (พระยามหานุภาพ) แต่งสมัยธนบุรี ส่วนเรื่องอื่นแต่งสมัยอยุธยา"},{"text":"สมัยธนบุรีมีวรรณกรรมน้อยกว่าอยุธยา น่าจะเป็นเพราะเหตุใด","a":"เป็นช่วงสั้นและอยู่ในภาวะสงคราม","b":"คนไทยเลิกอ่านหนังสือแล้ว","c":"มีกฎหมายห้ามแต่งวรรณกรรม","d":"ไม่มีพระมหากษัตริย์ปกครอง","correct":0,"explain":"เรื่องที่ ๑ ของหน่วยนี้ระบุว่าธนบุรีเป็นช่วงสั้น (15 ปี) และอยู่ในภาวะสงคราม จึงเน้นฟื้นฟูและสืบทอดจากอยุธยา งานใหม่จึงมีน้อย"},{"text":"ข้อใดสรุปประเพณีและพระราชพิธีสมัยธนบุรีได้ถูกต้อง","a":"สร้างใหม่ทั้งหมด ไม่เกี่ยวกับอยุธยา","b":"รับมาจากชาติตะวันตก","c":"ยกเลิกประเพณีเดิมทั้งหมด","d":"สืบทอดและฟื้นฟูจากอยุธยา","correct":3,"explain":"สไลด์สรุปว่า ธนบุรีสืบทอดและฟื้นฟูประเพณีและพระราชพิธีจากสมัยอยุธยา"},{"text":"พบว่าผู้แต่งวรรณกรรมบางเรื่องในสองแหล่งไม่ตรงกัน ควรทำอย่างไรเหมาะสมที่สุด","a":"เชื่อแหล่งแรกที่เจอทันที","b":"ตรวจสอบกับหนังสือเรียนก่อนสรุป","c":"เดาชื่อผู้แต่งเอาเอง","d":"ไม่ต้องสนใจผู้แต่งเลย","correct":1,"explain":"ข้อควรรู้ในสไลด์ระบุว่าผู้แต่งวรรณกรรมบางเรื่องยังมีข้อถกเถียง ควรตรวจสอบกับหนังสือเรียน"}]},{"id":"exam-his-06","name":"ประวัติ ม.2 · เรื่องที่ 6 บุคคลสำคัญสมัยอยุธยา","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 7 บุคคลสำคัญสมัยอยุธยาและธนบุรี · เรื่องที่ ๑","questions":[{"text":"สมเด็จพระบรมไตรโลกนาถให้ใครดูแลฝ่ายทหาร","a":"สมุหนายก","b":"สมุหพระกลาโหม","c":"จตุสดมภ์","d":"เจ้าเมือง","correct":1,"explain":"พระบรมไตรโลกนาถแยกการปกครองเป็น 2 ฝ่าย คือ ฝ่ายทหาร (สมุหพระกลาโหม) และฝ่ายพลเรือน (สมุหนายก)"},{"text":"ชาติตะวันตกชาติแรกที่ติดต่อกับอยุธยาคือชาติใด","a":"โปรตุเกส","b":"ฝรั่งเศส","c":"อังกฤษ","d":"ฮอลันดา","correct":0,"explain":"สมัยสมเด็จพระรามาธิบดีที่ 2 ทำสัญญาทางไมตรีกับโปรตุเกส ชาติตะวันตกชาติแรกที่ติดต่อกับอยุธยา"},{"text":"สมเด็จพระนเรศวรประกาศอิสรภาพที่เมืองใด","a":"เมืองลพบุรี","b":"เมืองพิษณุโลก","c":"เมืองจันทบูร","d":"เมืองแครง","correct":3,"explain":"พ.ศ. 2127 สมเด็จพระนเรศวรประกาศอิสรภาพที่เมืองแครง"},{"text":"การประกาศอิสรภาพ พ.ศ. 2127 มีผลต่ออยุธยาอย่างไร","a":"เป็นประเทศราชของฝรั่งเศส","b":"เสียกรุงให้พม่าทันที","c":"พ้นจากการเป็นประเทศราชของพม่า","d":"ย้ายราชธานีไปลพบุรี","correct":2,"explain":"การประกาศอิสรภาพที่เมืองแครงทำให้อยุธยาพ้นจากการเป็นประเทศราชของพม่า"},{"text":"สมเด็จพระสุริโยทัยได้รับยกย่องเป็นวีรสตรี เพราะเหตุใด","a":"ทรงช้างปกป้องพระสวามีจนสิ้นพระชนม์","b":"ทรงแต่งวรรณคดีไว้เป็นจำนวนมาก","c":"ทรงสร้างวัดจุฬามณีที่พิษณุโลก","d":"ทรงส่งคณะราชทูตไปฝรั่งเศส","correct":0,"explain":"พระสุริโยทัยปลอมพระองค์เป็นชาย ทรงช้างออกรบ ขับช้างเข้าขวางเพื่อปกป้องสมเด็จพระมหาจักรพรรดิจนสิ้นพระชนม์บนคอช้าง"},{"text":"ถ้าต้องการศึกษาความสัมพันธ์อยุธยากับฝรั่งเศส ควรศึกษาเรื่องของใคร","a":"สมเด็จพระบรมไตรโลกนาถ","b":"สมเด็จพระนารายณ์มหาราช","c":"สมเด็จพระสุริโยทัย","d":"สมเด็จพระรามาธิบดีที่ 2","correct":1,"explain":"สมเด็จพระนารายณ์เจริญสัมพันธไมตรีกับฝรั่งเศส ส่งคณะราชทูตนำโดยออกพระวิสุทธสุนทร (โกษาปาน)"},{"text":"“แยกฝ่ายทหาร–พลเรือน ปรับจตุสดมภ์ ตรากฎหมายศักดินา” ควรยกย่องกษัตริย์องค์นี้ว่าอะไร","a":"วีรสตรีผู้เสียสละ","b":"ผู้กอบกู้เอกราช","c":"นักปฏิรูปการปกครอง","d":"ผู้เจริญไมตรีกับฝรั่งเศส","correct":2,"explain":"ผลงานทั้งหมดเป็นของสมเด็จพระบรมไตรโลกนาถ ซึ่งสไลด์ยกย่องว่าเป็นนักปฏิรูปการปกครอง"},{"text":"ชัยชนะในสงครามยุทธหัตถี พ.ศ. 2135 ส่งผลต่ออยุธยาอย่างไร","a":"อยุธยาเป็นประเทศราชของพม่า","b":"อยุธยาเลิกติดต่อกับต่างชาติ","c":"อยุธยาต้องย้ายราชธานี","d":"บ้านเมืองมั่นคง ขยายอาณาเขตกว้าง","correct":3,"explain":"สไลด์ระบุว่าสมเด็จพระนเรศวรทรงชนะยุทธหัตถี บ้านเมืองมั่นคง และขยายอาณาเขตกว้างขวาง"},{"text":"ข้อใดเรียงเหตุการณ์สมัยอยุธยาได้ถูกต้อง","a":"ประกาศอิสรภาพ → พระบรมไตรโลกนาถครองราชย์ → พระนารายณ์ครองราชย์","b":"พระบรมไตรโลกนาถครองราชย์ → ประกาศอิสรภาพ → พระนารายณ์ครองราชย์","c":"พระนารายณ์ครองราชย์ → ประกาศอิสรภาพ → พระบรมไตรโลกนาถครองราชย์","d":"ประกาศอิสรภาพ → พระนารายณ์ครองราชย์ → พระบรมไตรโลกนาถครองราชย์","correct":1,"explain":"เส้นเวลาในสไลด์: พระบรมไตรโลกนาถครองราชย์ (1991) → ประกาศอิสรภาพ (2127) → พระนารายณ์ครองราชย์ (2199)"},{"text":"คุณธรรมของสมเด็จพระสุริโยทัยข้อใด นักเรียนนำมาใช้ในชีวิตได้เหมาะสมที่สุด","a":"เสียสละและรักครอบครัว","b":"ใช้กำลังแก้ทุกปัญหา","c":"เอาตัวรอดเพียงคนเดียว","d":"ไม่สนใจความรู้สึกผู้อื่น","correct":0,"explain":"สไลด์สรุปคุณธรรมของพระสุริโยทัยว่า กล้าหาญ เสียสละ รักครอบครัวและบ้านเมือง"}]},{"id":"exam-his-07","name":"ประวัติ ม.2 · เรื่องที่ 7 บุคคลสำคัญสมัยธนบุรี","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 7 บุคคลสำคัญสมัยอยุธยาและธนบุรี · เรื่องที่ ๒","questions":[{"text":"ใครอัญเชิญพระแก้วมรกตมายังกรุงธนบุรี","a":"สมเด็จพระเจ้าตากสิน","b":"เจ้าพระยามหากษัตริย์ศึก","c":"เจ้าพระยาสุรสีห์ (บุญมา)","d":"สมเด็จพระนเรศวร","correct":1,"explain":"สมเด็จเจ้าพระยามหากษัตริย์ศึก (ทองด้วง) ยกทัพตีเวียงจันทน์ อัญเชิญพระแก้วมรกตมายังกรุงธนบุรี พ.ศ. 2322"},{"text":"ก่อนกู้เอกราช พระเจ้าตากสินตีเมืองใดเป็นฐานกำลัง","a":"เชียงใหม่","b":"พิษณุโลก","c":"จันทบูร","d":"เวียงจันทน์","correct":2,"explain":"พระเจ้าตากสินตีเมืองจันทบูรเป็นฐานกำลัง แล้วยกทัพเรือขับไล่พม่าที่ค่ายโพธิ์สามต้น"},{"text":"เจ้าพระยาสุรสีห์ (บุญมา) ร่วมขับไล่พม่าออกจากดินแดนใด","a":"ล้านนา","b":"ล้านช้าง","c":"เขมร","d":"หัวเมืองมลายู","correct":0,"explain":"เจ้าพระยาสุรสีห์ร่วมตีเมืองเชียงใหม่ ขับไล่พม่าออกจากล้านนา"},{"text":"ต่อมาสมเด็จเจ้าพระยามหากษัตริย์ศึก (ทองด้วง) ได้เป็นใคร","a":"ราชทูตที่เดินทางไปฝรั่งเศส","b":"เจ้าเมืองเชียงใหม่ในล้านนา","c":"แม่ทัพพม่าที่ค่ายโพธิ์สามต้น","d":"รัชกาลที่ 1 ผู้สถาปนารัตนโกสินทร์","correct":3,"explain":"สมเด็จเจ้าพระยามหากษัตริย์ศึกปราบดาภิเษกเป็นรัชกาลที่ 1 สถาปนากรุงรัตนโกสินทร์ พ.ศ. 2325"},{"text":"พระเจ้าตากสินฟื้นฟูเศรษฐกิจด้วยวิธีใด","a":"ทำเหมืองทองคำ","b":"ค้าขายกับจีน","c":"ยกเลิกภาษีทั้งหมด","d":"ปิดประเทศ","correct":1,"explain":"สไลด์ระบุว่าพระเจ้าตากสินฟื้นฟูเศรษฐกิจด้วยการค้าขายกับจีน"},{"text":"“ร่วมรักษาเมืองพิษณุโลกในศึกอะแซหวุ่นกี้ ต่อมาเป็นวังหน้าในรัชกาลที่ 1” คือใคร","a":"เจ้าพระยาสุรสีห์ (บุญมา)","b":"สมเด็จพระนเรศวรมหาราช","c":"สมเด็จพระนารายณ์มหาราช","d":"สมเด็จพระบรมไตรโลกนาถ","correct":0,"explain":"เจ้าพระยาสุรสีห์ร่วมรักษาเมืองพิษณุโลกในศึกอะแซหวุ่นกี้ และต่อมาดำรงพระยศเป็นกรมพระราชวังบวรมหาสุรสิงหนาท (วังหน้า)"},{"text":"ถ้าทำรายงานเรื่อง “ผู้กอบกู้เอกราชหลังเสียกรุง พ.ศ. 2310” ควรเลือกบุคคลใด","a":"สมเด็จพระบรมไตรโลกนาถ","b":"สมเด็จพระรามาธิบดีที่ 2","c":"สมเด็จพระเจ้าตากสินมหาราช","d":"สมเด็จพระนารายณ์มหาราช","correct":2,"explain":"สมเด็จพระเจ้าตากสินมหาราชตีฝ่าวงล้อมพม่า ขับไล่พม่าที่ค่ายโพธิ์สามต้น และสถาปนากรุงธนบุรี จึงเป็นผู้กอบกู้เอกราช"},{"text":"พระเจ้าตากสินปราบชุมนุมต่างๆ เพื่อจุดประสงค์ใด","a":"เพื่อแย่งค้าขายกับจีน","b":"เพื่อสร้างวัดแจ้ง","c":"เพื่อส่งทูตไปฝรั่งเศส","d":"เพื่อรวมแผ่นดินเป็นปึกแผ่น","correct":3,"explain":"สไลด์ระบุว่าพระเจ้าตากสินปราบชุมนุมต่างๆ เพื่อรวมแผ่นดินเป็นปึกแผ่น"},{"text":"ข้อใดเรียงเหตุการณ์สมัยธนบุรีได้ถูกต้อง","a":"สถาปนากรุงธนบุรี → ตีฝ่าวงล้อม → สถาปนารัตนโกสินทร์ → อัญเชิญพระแก้วมรกต","b":"ตีฝ่าวงล้อม → สถาปนากรุงธนบุรี → อัญเชิญพระแก้วมรกต → สถาปนารัตนโกสินทร์","c":"อัญเชิญพระแก้วมรกต → ตีฝ่าวงล้อม → สถาปนากรุงธนบุรี → สถาปนารัตนโกสินทร์","d":"ตีฝ่าวงล้อม → อัญเชิญพระแก้วมรกต → สถาปนารัตนโกสินทร์ → สถาปนากรุงธนบุรี","correct":1,"explain":"เส้นเวลาในสไลด์: ตีฝ่าวงล้อม (2309) → สถาปนากรุงธนบุรี (2310) → อัญเชิญพระแก้วมรกต (2322) → สถาปนารัตนโกสินทร์ (2325)"},{"text":"ข้อใดเป็นการนำคุณธรรม “ความสามัคคี” ของบุคคลสำคัญมาใช้ได้ดีที่สุด","a":"ช่วยเพื่อนทำงานกลุ่มจนสำเร็จ","b":"แยกทำงานคนเดียวไม่ฟังใคร","c":"ทะเลาะกับเพื่อนในกลุ่ม","d":"ให้เพื่อนทำแทนทั้งหมด","correct":0,"explain":"ความสามัคคีเป็น 1 ใน 5 คุณธรรมเด่นของบุคคลสำคัญสมัยธนบุรี การร่วมมือกับเพื่อนจนงานสำเร็จจึงตรงที่สุด"}]},{"id":"exam-his-08","name":"ประวัติ ม.2 · เรื่องที่ 8 พัฒนาการของภูมิภาคเอเชีย","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 8 พัฒนาการของภูมิภาคต่างๆ ในเอเชีย · เรื่องที่ ๑","questions":[{"text":"ภูมิภาคใดไม่มีทางออกทะเล และอยู่บนเส้นทางสายไหม","a":"เอเชียใต้","b":"เอเชียกลาง","c":"เอเชียตะวันออก","d":"เอเชียตะวันตกเฉียงใต้","correct":1,"explain":"เอเชียกลางไม่มีทางออกทะเล อยู่บนเส้นทางสายไหม เกิดเมืองการค้า เช่น ซามาร์คันด์"},{"text":"อารยธรรมเมโสโปเตเมีย เกิดบริเวณลุ่มแม่น้ำใด","a":"หวางเหอ–แยงซี","b":"สินธุ–คงคา","c":"ไทกริส–ยูเฟรทีส","d":"แม่น้ำคงคา","correct":2,"explain":"อารยธรรมเมโสโปเตเมียเกิดที่ลุ่มแม่น้ำไทกริส–ยูเฟรทีส ในเอเชียตะวันตกเฉียงใต้"},{"text":"ญี่ปุ่นทันสมัยขึ้นหลังการปฏิรูปสมัยใด","a":"สมัยสุโขทัย","b":"สมัยอยุธยา","c":"สมัยธนบุรี","d":"สมัยเมจิ","correct":3,"explain":"สไลด์ระบุว่าญี่ปุ่นปฏิรูปสมัยเมจิจนทันสมัย ปัจจุบันเป็นศูนย์กลางอุตสาหกรรมและเทคโนโลยี"},{"text":"เอเชียตะวันตกเฉียงใต้มีสภาพภูมิศาสตร์อย่างไร","a":"แห้งแล้ง ส่วนใหญ่เป็นทะเลทราย","b":"หนาวจัด มีหิมะปกคลุมทั้งปี","c":"ฝนตกชุก เป็นป่าดิบชื้นทั้งหมด","d":"เป็นหมู่เกาะ มีภูเขาไฟจำนวนมาก","correct":0,"explain":"เอเชียตะวันตกเฉียงใต้ส่วนใหญ่เป็นทะเลทรายและที่ราบสูง อากาศแห้งแล้ง"},{"text":"เมืองซามาร์คันด์เกิดเป็นเมืองการค้า เพราะเหตุใด","a":"อยู่ติดทะเลใหญ่","b":"มีน้ำมันมาก","c":"อยู่บนเส้นทางสายไหม","d":"เป็นเกาะภูเขาไฟ","correct":2,"explain":"เอเชียกลางอยู่บนเส้นทางสายไหม จึงเกิดเมืองการค้า เช่น ซามาร์คันด์"},{"text":"ถ้าต้องการศึกษาดินแดนที่เป็นกำเนิดศาสนายูดาย คริสต์ อิสลาม ควรไปประเทศใด","a":"ญี่ปุ่น","b":"อิสราเอล","c":"คาซัคสถาน","d":"ภูฏาน","correct":1,"explain":"ศาสนายูดาย คริสต์ อิสลาม กำเนิดในเอเชียตะวันตกเฉียงใต้ ซึ่งสไลด์ยกตัวอย่างประเทศอิสราเอลในภูมิภาคนี้"},{"text":"ทัชมาฮาล เป็นหลักฐานของจักรวรรดิใด","a":"จักรวรรดิออตโตมัน","b":"จักรวรรดิโมกุล","c":"จักรวรรดิมองโกล","d":"สหภาพโซเวียต","correct":1,"explain":"สไลด์เอเชียใต้แสดงภาพทัชมาฮาล สมัยจักรวรรดิโมกุล"},{"text":"เพราะเหตุใดเอเชียตะวันตกเฉียงใต้ในปัจจุบันจึงสำคัญต่อเศรษฐกิจโลก","a":"มีป่าไม้มากที่สุด","b":"เป็นศูนย์กลางเทคโนโลยี","c":"ปลูกข้าวมากที่สุด","d":"เป็นแหล่งน้ำมันสำคัญของโลก","correct":3,"explain":"แม้ส่วนใหญ่เป็นทะเลทราย แต่ปัจจุบันเอเชียตะวันตกเฉียงใต้เป็นแหล่งน้ำมันสำคัญของโลก ส่วนศูนย์กลางเทคโนโลยีคือญี่ปุ่น"},{"text":"จากการเรียนทั้ง 4 ภูมิภาค สรุปได้ว่าอย่างไร","a":"ภูมิศาสตร์ต่างกัน ทำให้พัฒนาการต่างกัน","b":"ทุกภูมิภาคพัฒนาเหมือนกันหมด","c":"ภูมิศาสตร์ไม่มีผลต่อพัฒนาการ","d":"ทุกภูมิภาคเป็นทะเลทรายเหมือนกัน","correct":0,"explain":"แนวคิดหลักของหน่วยนี้คือ ภูมิศาสตร์ที่ต่างกัน สร้างพัฒนาการที่ต่างกัน"},{"text":"ปีได้รับเอกราชของเอเชียกลางในสองแหล่งไม่ตรงกัน ควรทำอย่างไรเหมาะสมที่สุด","a":"เลือกปีที่ตนเองจำง่ายที่สุด","b":"เชื่อแหล่งแรกที่ค้นเจอทันที","c":"ตรวจสอบกับหนังสือเรียนก่อนสรุป","d":"ไม่ต้องสนใจปีศักราชเลย","correct":2,"explain":"ข้อควรรู้ในสไลด์ระบุว่าการจัดกลุ่มประเทศและปีศักราชในเอกสารต่างๆ อาจไม่ตรงกัน ควรตรวจสอบกับหนังสือเรียน"}]},{"id":"exam-his-09","name":"ประวัติ ม.2 · เรื่องที่ 9 อารยธรรมจีน","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 9 แหล่งอารยธรรมโบราณในเอเชีย · เรื่องที่ ๑","questions":[{"text":"สมัยประวัติศาสตร์ของจีนเริ่มที่ราชวงศ์ใด","a":"ราชวงศ์ฉิน","b":"ราชวงศ์ชาง","c":"ราชวงศ์ฮั่น","d":"ราชวงศ์ชิง","correct":1,"explain":"สมัยประวัติศาสตร์ของจีนเริ่มที่ราชวงศ์ชาง มีอักษรจารึกบนกระดองเต่าและกระดูกสัตว์"},{"text":"จักรพรรดิองค์ใดรวมแผ่นดินจีน และสร้างกำแพงเมืองจีน","a":"ขงจื๊อ","b":"เล่าจื๊อ","c":"ฉินสื่อหวงตี้","d":"พระเจ้าอโศกมหาราช","correct":2,"explain":"จักรพรรดิฉินสื่อหวงตี้ (ราชวงศ์ฉิน) รวมแผ่นดินจีน และสร้างกำแพงเมืองจีนต่อเชื่อมกัน ส่วนขงจื๊อและเล่าจื๊อเป็นนักปรัชญา"},{"text":"อักษรจีนยุคแรกจารึกไว้บนสิ่งใด","a":"แผ่นทองคำและเงิน","b":"ใบลานและสมุดไทย","c":"ผ้าไหมและกระดาษ","d":"กระดองเต่าและกระดูกสัตว์","correct":3,"explain":"ราชวงศ์ชางมีอักษรจารึกบนกระดองเต่าและกระดูกสัตว์"},{"text":"แม่น้ำหวางเหอได้ชื่อว่า “ความเศร้าโศกของจีน” เพราะเหตุใด","a":"เพราะน้ำท่วมบ่อย","b":"เพราะน้ำแห้งทุกปี","c":"เพราะไหลผ่านทะเลทราย","d":"เพราะไม่มีดินตะกอน","correct":0,"explain":"หวางเหอมีดินตะกอนอุดมสมบูรณ์ แต่น้ำท่วมบ่อย จึงได้ชื่อว่าความเศร้าโศกของจีน"},{"text":"หยางเชาและหลงซาน เป็นชุมชนแบบใด","a":"เมืองการค้าบนเส้นทางสายไหม","b":"ชุมชนเกษตรกรรมยุคหินใหม่","c":"ราชธานีของราชวงศ์ฉิน","d":"เมืองท่าค้าสำเภา","correct":1,"explain":"สไลด์ระบุว่าหยางเชา (เครื่องปั้นดินเผาเขียนสี) และหลงซาน (เครื่องปั้นดินเผาสีดำ) เป็นชุมชนเกษตรกรรมยุคหินใหม่"},{"text":"เห็นเข็มทิศ ดินปืน และการพิมพ์ ควรนึกถึงราชวงศ์ใดของจีน","a":"ชาง · โจว","b":"โจว · ฉิน","c":"ถัง · ซ่ง","d":"ฉิน · ชาง","correct":2,"explain":"สไลด์ระบุว่าราชวงศ์ถัง · ซ่ง รุ่งเรืองด้านศิลปะ การพิมพ์ เข็มทิศ ดินปืน"},{"text":"การกินก๋วยเตี๋ยวและเทศกาลตรุษจีนในไทย แสดงถึงสิ่งใด","a":"อิทธิพลอารยธรรมจีนต่อไทย","b":"อิทธิพลอารยธรรมอินเดีย","c":"อิทธิพลชาติตะวันตก","d":"ไทยไม่รับวัฒนธรรมใดเลย","correct":0,"explain":"สไลด์ “อิทธิพลต่อไทย” ระบุว่า ก๋วยเตี๋ยว ตรุษจีน สารทจีน คำยืมภาษาจีน และเครื่องลายคราม มาจากอารยธรรมจีน"},{"text":"จักรพรรดิฉินกำหนดมาตรฐานตัวอักษรและมาตราชั่งตวงวัด หลังรวมแผ่นดิน เพื่ออะไรมากที่สุด","a":"ทำให้จีนแตกออกเป็นหลายแคว้น","b":"ทำให้คนจีนเลิกใช้ตัวอักษร","c":"ทำให้ค้าขายกันไม่ได้อีกต่อไป","d":"ให้ทั้งแผ่นดินใช้มาตรฐานเดียวกัน","correct":3,"explain":"เมื่อรวมแผ่นดินจีนแล้ว การกำหนดมาตรฐานตัวอักษรและมาตราชั่งตวงวัดทำให้ทุกส่วนของแผ่นดินใช้มาตรฐานเดียวกัน ตัวเลือกอื่นเป็นผลตรงข้ามกับการรวมแผ่นดิน"},{"text":"ข้อใดเรียงราชวงศ์จีนได้ถูกต้อง","a":"ฉิน → ชาง → ฮั่น → โจว","b":"ชาง → โจว → ฉิน → ฮั่น","c":"ฮั่น → ฉิน → โจว → ชาง","d":"โจว → ฮั่น → ชาง → ฉิน","correct":1,"explain":"สไลด์เรียงราชวงศ์ไว้คือ ชาง → โจว → ฉิน → ฮั่น ถึง ชิง (ราชวงศ์สุดท้าย)"},{"text":"หวางเหอน้ำท่วมบ่อย แต่ชาวจีนโบราณยังเลือกอยู่ริมแม่น้ำ การตัดสินใจนี้เป็นอย่างไร","a":"ไม่สมเหตุสมผล เพราะไม่มีน้ำใช้","b":"สมเหตุสมผล เพราะไม่เคยมีน้ำท่วม","c":"สมเหตุสมผล เพราะดินอุดมเหมาะเพาะปลูก","d":"ไม่สมเหตุสมผล เพราะดินแห้งแล้ง","correct":2,"explain":"แม้น้ำท่วมบ่อย แต่หวางเหอมีดินตะกอนอุดมสมบูรณ์ เหมาะแก่การเพาะปลูก การเลือกอยู่ริมแม่น้ำจึงสมเหตุสมผล"}]},{"id":"exam-his-10","name":"ประวัติ ม.2 · เรื่องที่ 10 อารยธรรมอินเดีย","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 9 แหล่งอารยธรรมโบราณในเอเชีย · เรื่องที่ ๒","questions":[{"text":"เมืองสำคัญของอารยธรรมลุ่มแม่น้ำสินธุ คือเมืองใด","a":"ปักกิ่งและซีอาน","b":"ซามาร์คันด์และเปตรา","c":"ฮารัปปาและโมเฮนโจดาโร","d":"พุทธคยาและสาญจี","correct":2,"explain":"เมืองสำคัญของอารยธรรมลุ่มแม่น้ำสินธุ คือ ฮารัปปาและโมเฮนโจดาโร (ปัจจุบันอยู่ในปากีสถาน)"},{"text":"ราชวงศ์ใดเป็นยุคทองของอินเดีย","a":"ราชวงศ์เมารยะ","b":"ราชวงศ์คุปตะ","c":"ราชวงศ์ชาง","d":"จักรวรรดิโมกุล","correct":1,"explain":"ราชวงศ์คุปตะเป็นยุคทองของอินเดีย เจริญด้านคณิตศาสตร์ ดาราศาสตร์ วรรณกรรม"},{"text":"ข้อใดเป็นวรรณะหนึ่งในระบบวรรณะ 4 ของอินเดีย","a":"ไพร่","b":"ทาส","c":"ขุนนาง","d":"แพศย์","correct":3,"explain":"ระบบวรรณะ 4 ของอินเดีย คือ พราหมณ์ กษัตริย์ แพศย์ ศูทร ส่วนไพร่ ทาส ขุนนาง เป็นชนชั้นในสังคมไทยสมัยอยุธยา"},{"text":"ตราประทับของอารยธรรมลุ่มแม่น้ำสินธุมีลักษณะสำคัญอย่างไร","a":"มีอักษรที่ยังอ่านไม่ออก","b":"เป็นอักษรไทยโบราณ","c":"อ่านออกครบทุกตัวแล้ว","d":"ไม่มีตัวอักษรใดเลย","correct":0,"explain":"สไลด์ระบุว่าตราประทับลุ่มสินธุมีอักษรซึ่งยังอ่านไม่ออก"},{"text":"พระเจ้าอโศกมหาราชส่งสมณทูตออกไป เพื่ออะไร","a":"ไปค้าขายเครื่องเทศ","b":"เผยแผ่พระพุทธศาสนา","c":"ไปทำสงครามกับจีน","d":"ไปเรียนคณิตศาสตร์","correct":1,"explain":"พระเจ้าอโศกมหาราช (ราชวงศ์เมารยะ) ทำนุบำรุงและส่งสมณทูตเผยแผ่พระพุทธศาสนา"},{"text":"รามเกียรติ์ของไทย ได้รับอิทธิพลจากสิ่งใดของอินเดีย","a":"คัมภีร์ฤคเวท","b":"ระบบวรรณะ","c":"มหากาพย์รามายณะ","d":"ระบบเลขศูนย์","correct":2,"explain":"อินเดียมีมหากาพย์รามายณะและมหาภารตะ สไลด์ “อิทธิพลต่อไทย” ระบุรามเกียรติ์ไว้ด้วย"},{"text":"ผังเมืองเป็นตาราง มีระบบระบายน้ำและห้องอาบน้ำสาธารณะ เป็นหลักฐานของอารยธรรมใด","a":"ลุ่มแม่น้ำสินธุ","b":"ลุ่มแม่น้ำหวางเหอ","c":"ราชวงศ์คุปตะ","d":"ราชวงศ์เมารยะ","correct":0,"explain":"สไลด์ระบุว่าอารยธรรมลุ่มแม่น้ำสินธุมีผังเมืองเป็นตาราง มีระบบระบายน้ำและห้องอาบน้ำสาธารณะ"},{"text":"เลขศูนย์ที่ใช้กันทั่วโลก แสดงว่าราชวงศ์คุปตะโดดเด่นด้านใด","a":"การทำสงคราม","b":"สถาปัตยกรรมเจดีย์","c":"การค้าทางทะเล","d":"คณิตศาสตร์","correct":3,"explain":"ราชวงศ์คุปตะเจริญด้านคณิตศาสตร์ (ระบบตัวเลขและเลขศูนย์) ดาราศาสตร์ และวรรณกรรม"},{"text":"ข้อใดสรุปอิทธิพลของอินเดียต่อไทยได้ครบที่สุด","a":"อาหารและการแต่งกายเท่านั้น","b":"ศาสนา พิธีกรรม ภาษา และวรรณกรรม","c":"ตัวอักษรจีนและก๋วยเตี๋ยว","d":"รับระบบวรรณะมาทั้งหมด","correct":1,"explain":"สไลด์ระบุอิทธิพลต่อไทย คือ พระพุทธศาสนา พระราชพิธีแบบพราหมณ์ คำบาลี–สันสกฤต และรามเกียรติ์ ซึ่งรวมได้เป็นศาสนา พิธีกรรม ภาษา และวรรณกรรม"},{"text":"ถ้าเลือกไปได้ที่เดียวในอินเดียเพื่อศึกษาพระพุทธศาสนา ที่ใดเหมาะที่สุด","a":"เมืองโมเฮนโจดาโร","b":"ทัชมาฮาล สมัยโมกุล","c":"มหาโพธิวิหาร พุทธคยา","d":"เมืองเปอร์เซโปลิส","correct":2,"explain":"มหาโพธิวิหาร พุทธคยา เกี่ยวข้องกับพระพุทธศาสนาโดยตรง ส่วนโมเฮนโจดาโรเป็นเมืองลุ่มสินธุ ทัชมาฮาลเป็นสมัยโมกุล และเปอร์เซโปลิสอยู่ในอิหร่าน"}]},{"id":"exam-his-11","name":"ประวัติ ม.2 · เรื่องที่ 11 แหล่งมรดกโลกในเอเชีย","subject":"ประวัติศาสตร์","unit":"หน่วยที่ 9 แหล่งอารยธรรมโบราณในเอเชีย · เรื่องที่ ๓","questions":[{"text":"องค์การใดเป็นผู้ประกาศแหล่งมรดกโลก","a":"อาเซียน (ASEAN)","b":"ยูเนสโก (UNESCO)","c":"เอเปก (APEC)","d":"สหภาพโซเวียต","correct":1,"explain":"องค์การยูเนสโก (UNESCO) เป็นผู้ประกาศแหล่งมรดกโลก"},{"text":"นครวัด อยู่ในประเทศใด","a":"กัมพูชา","b":"อินโดนีเซีย","c":"อินเดีย","d":"จอร์แดน","correct":0,"explain":"นครวัดอยู่ในกัมพูชา ส่วนบุโรพุทโธอยู่ในอินโดนีเซีย"},{"text":"ข้อใดเป็นมรดกโลกทางธรรมชาติของไทย","a":"แหล่งโบราณคดีบ้านเชียง","b":"นครประวัติศาสตร์อยุธยา","c":"ทุ่งใหญ่นเรศวร–ห้วยขาแข้ง","d":"เมืองประวัติศาสตร์สุโขทัย","correct":2,"explain":"ทุ่งใหญ่นเรศวร–ห้วยขาแข้งเป็นมรดกโลกทางธรรมชาติ ส่วนอีก 3 แห่งเป็นมรดกโลกทางวัฒนธรรม"},{"text":"“มรดกโลก” หมายถึงข้อใด","a":"สถานที่ที่มีคนเที่ยวมากที่สุด","b":"สถานที่ที่สร้างใหม่ที่สุด","c":"สถานที่ที่เป็นของเอกชน","d":"สถานที่มีคุณค่าโดดเด่น ควรอนุรักษ์","correct":3,"explain":"มรดกโลก คือ สถานที่ที่ยูเนสโกประกาศว่ามีคุณค่าโดดเด่นเป็นสากล ควรอนุรักษ์ไว้ให้มนุษยชาติ"},{"text":"มรดกโลก “แบบผสม” หมายถึงอะไร","a":"โบราณสถานอย่างเดียว","b":"วัฒนธรรมรวมกับธรรมชาติ","c":"ป่าไม้อย่างเดียว","d":"เมืองใหม่สมัยปัจจุบัน","correct":1,"explain":"มรดกโลกแบ่งเป็น วัฒนธรรม ธรรมชาติ และแบบผสม (วัฒนธรรม + ธรรมชาติ)"},{"text":"นครประวัติศาสตร์พระนครศรีอยุธยา จัดเป็นมรดกโลกประเภทใด","a":"มรดกโลกทางธรรมชาติ","b":"มรดกโลกแบบผสม","c":"มรดกโลกทางวัฒนธรรม","d":"ไม่ได้เป็นมรดกโลก","correct":2,"explain":"มรดกโลกทางวัฒนธรรม ได้แก่ โบราณสถาน เมืองเก่า อยุธยาเป็นนครประวัติศาสตร์จึงจัดเป็นมรดกโลกทางวัฒนธรรม"},{"text":"ไปเที่ยวอุทยานประวัติศาสตร์สุโขทัย ข้อใดปฏิบัติถูกต้อง","a":"ปีนโบราณสถานเพื่อถ่ายรูป","b":"ขีดเขียนชื่อบนกำแพง","c":"ทิ้งขยะไว้ข้างทาง","d":"ปฏิบัติตามกฎของสถานที่","correct":3,"explain":"วิธีอนุรักษ์มรดกโลก คือ ไม่ขีดเขียนหรือปีนป่าย ไม่ทิ้งขยะ ปฏิบัติตามกฎของสถานที่ และเผยแพร่ความรู้อย่างถูกต้อง"},{"text":"แหล่งมรดกโลกช่วยเศรษฐกิจท้องถิ่นได้อย่างไร","a":"ดึงดูดนักท่องเที่ยว สร้างรายได้","b":"ทำให้คนท้องถิ่นต้องย้ายออก","c":"ทำให้ไม่มีใครมาเที่ยว","d":"ทำให้ห้ามค้าขายทุกชนิด","correct":0,"explain":"สไลด์ระบุว่ามรดกโลกดึงดูดนักท่องเที่ยว สร้างรายได้และอาชีพให้คนท้องถิ่น"},{"text":"พุทธ พราหมณ์–ฮินดู และขงจื๊อ ยังเป็นรากฐานวิถีชีวิตชาวเอเชีย สรุปได้ว่าอย่างไร","a":"อารยธรรมโบราณหายไปหมดแล้ว","b":"ชาวเอเชียไม่นับถือศาสนาใดเลย","c":"อารยธรรมโบราณยังมีอิทธิพลต่อปัจจุบัน","d":"ปัจจุบันใช้แต่วัฒนธรรมตะวันตก","correct":2,"explain":"สไลด์ “อิทธิพลของอารยธรรมโบราณต่อเอเชียปัจจุบัน” ระบุว่าศาสนาและปรัชญาเหล่านี้ยังเป็นรากฐานวิถีชีวิตชาวเอเชีย"},{"text":"ข้อใดเป็นวิธีอนุรักษ์มรดกโลกที่เหมาะสมที่สุดสำหรับนักเรียน","a":"แชร์ข้อมูลผิดๆ ให้คนสนใจ","b":"เผยแพร่ความรู้อย่างถูกต้อง","c":"เก็บเศษโบราณวัตถุกลับบ้าน","d":"ปีนโบราณสถานเพื่อถ่ายภาพ","correct":1,"explain":"การเผยแพร่ความรู้อย่างถูกต้องเป็น 1 ใน 4 วิธีอนุรักษ์มรดกโลกในสไลด์ ส่วนข้ออื่นทำลายหรือบิดเบือนมรดกโลก"}]}];
